INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m01', 'M01 - Fundamentos da IA', 'Conceitos básicos, IA no cotidiano e diferença entre IA e automação.', 1, 4, true, '/covers/m01-fundamentos-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-1-1', 'm01', 'O que é Inteligência Artificial', 'Fundamentos e evolução da IA aplicada ao escritório.', 'Entenda o que é IA, sua história e por que ela importa para o profissional moderno.', '<h3>🎯 Objetivo da aula</h3><p>Compreender o conceito de Inteligência Artificial e por que ela está transformando o trabalho de escritório.</p><h3>📖 Explicação</h3><div><p>Inteligência Artificial (IA) é a área da computação que cria sistemas capazes de executar tarefas que, até pouco tempo, só humanos conseguiam: entender linguagem, reconhecer padrões, tomar decisões e aprender com a experiência.</p><p>Diferente de um programa tradicional — que segue regras fixas escritas por um programador — uma IA <strong>aprende a partir de exemplos</strong>. Quanto mais dados ela vê, melhor ela fica.</p><p>No escritório, a IA aparece de três formas práticas: como <strong>assistente</strong> (ChatGPT, Copilot), como <strong>automação inteligente</strong> (e-mails classificados sozinhos) e como <strong>análise de dados</strong> (gráficos e insights gerados a partir de planilhas).</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Você cola um e-mail confuso no ChatGPT e ele devolve um resumo em 3 linhas.</li><li>O Outlook sugere uma resposta pronta com base no histórico da conversa.</li><li>O Excel cria automaticamente um gráfico ao identificar tendências na sua planilha.</li></ul><h3>🪜 Passo a passo</h3><ol><li>Identifique uma tarefa repetitiva que você faz toda semana.</li><li>Pergunte: "Essa tarefa exige criatividade ou só repetição?"</li><li>Se for repetitiva, anote como candidata a ser auxiliada por IA.</li><li>Escolha uma ferramenta gratuita (ChatGPT, por exemplo) e teste com ela.</li></ol><h3>💡 Dicas importantes</h3><ul><li>IA não é mágica — ela acerta mais quando você dá contexto claro.</li><li>Comece pequeno: use IA em uma tarefa por dia até virar hábito.</li><li>Sempre revise a saída da IA antes de enviar para outra pessoa.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Achar que a IA "sabe tudo" — ela inventa quando não tem certeza.</li><li>Colar informações confidenciais sem critério (sigilo de cliente, salários).</li><li>Aceitar a primeira resposta sem refinar o pedido.</li></ul><h3>📌 Resumo final</h3><p>IA é um sistema que aprende com dados para executar tarefas cognitivas. No escritório, ela atua como assistente, automatizador e analista — sempre sob supervisão humana.</p><h3>✏️ Exercício de fixação</h3><p>Liste 5 tarefas que você fez na última semana. Marque com 🤖 as que poderiam ser feitas (ou auxiliadas) por IA. Compartilhe com um colega.</p>', '', 1, 25, true, 'Compreender o conceito de Inteligência Artificial, sua evolução histórica e seu impacto no ambiente corporativo.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Olá! Bem-vindo à primeira aula do nosso curso. Hoje vamos descobrir juntos o que é Inteligência Artificial. Imagine um assistente que aprende com você, entende contexto e nunca dorme. É exatamente isso que a IA traz para o seu dia a dia. Vamos começar essa jornada?', 'Resumo em áudio: IA é tecnologia que aprende com dados. No escritório, serve como assistente, automatizador e analista. Sempre revise as respostas antes de usar.', 'Cena 1 (0–20s): Apresentação do instrutor e título da aula. Cena 2 (20–90s): Animação mostrando "computador antigo seguindo regras" vs "IA aprendendo". Cena 3 (90–180s): Três exemplos práticos no escritório. Cena 4 (180–240s): Mitos da IA. Cena 5 (240–300s): Call to action: "Pratique com ChatGPT hoje".', 'Abra o ChatGPT (ou outra ferramenta) e peça: "Liste 5 maneiras de eu usar IA na minha rotina como [seu cargo]". Imprima ou salve a resposta. Escolha uma das 5 sugestões para testar amanhã.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os1', 'aula-1-1', 'IA em uma Frase Simples', 'Inteligência Artificial é uma ferramenta que aprende com exemplos e ajuda você a ler, resumir, escrever, organizar e decidir melhor. Pense nela como um assistente que prepara um rascunho para você revisar.', '/slides/m01/aula-1-1-01.png', 1),
  ('os2', 'aula-1-1', 'Antes e Depois da IA', 'Antes: você fazia tudo manualmente, começava do zero e gastava tempo organizando ideias. Com IA: você entrega contexto, recebe um primeiro rascunho e usa seu julgamento para corrigir, melhorar e aprovar.', '/slides/m01/aula-1-1-02.png', 2),
  ('os3', 'aula-1-1', 'O Caminho Correto', '1. Explique a tarefa em palavras simples
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q1', 'aula-1-1', 'Quiz: O que é Inteligência Artificial')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p1', 'q1', 'O que diferencia a IA de uma automação tradicional?', '[{"id":"a","texto":"A IA é mais rápida em execução."},{"id":"b","texto":"A IA aprende com dados e se adapta a situações novas, a automação segue regras fixas."},{"id":"c","texto":"A IA só funciona em nuvem."},{"id":"d","texto":"A IA precisa sempre de internet."}]'::jsonb, 'b', 1),
  ('p2', 'q1', 'Qual é uma boa prática ao usar IA no trabalho?', '[{"id":"a","texto":"Colar dados confidenciais sem revisar."},{"id":"b","texto":"Aceitar a primeira resposta sem refinar."},{"id":"c","texto":"Revisar a saída antes de compartilhar com outras pessoas."},{"id":"d","texto":"Usar IA apenas em tarefas criativas."}]'::jsonb, 'c', 2),
  ('p3', 'q1', 'Qual destes NÃO é exemplo típico de IA no escritório?', '[{"id":"a","texto":"Resumo automático de e-mail."},{"id":"b","texto":"Sugestão de resposta no Outlook."},{"id":"c","texto":"Cálculo simples de SOMA no Excel."},{"id":"d","texto":"Análise automática de tendências em dados."}]'::jsonb, 'c', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-1-2', 'm01', 'IA no Cotidiano', 'Como a IA já faz parte da nossa vida diária e profissional.', 'Reconheça a IA que você já usa todos os dias sem perceber.', '<h3>🎯 Objetivo da aula</h3><p>Reconhecer onde a IA já está presente no seu dia a dia, dentro e fora do escritório.</p><h3>📖 Explicação</h3><div><p>Muito antes do ChatGPT, a IA já estava ao seu redor: no GPS que recalcula a rota, no streaming que recomenda séries, no banco que detecta fraudes em milissegundos.</p><p>No trabalho, ela aparece em ferramentas que você já usa: o Outlook prioriza e-mails importantes, o Teams gera resumo de reunião, o Excel sugere gráficos. A diferença agora é que <strong>você pode comandar a IA diretamente</strong> em vez de só usar o que ela faz nos bastidores.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>GPS do Waze recalcula a rota com base no trânsito em tempo real.</li><li>Outlook coloca e-mails importantes acima dos promocionais.</li><li>Teams gera transcrição e ata da reunião automaticamente.</li><li>Banco bloqueia uma compra suspeita antes de você perceber.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Observe um dia inteiro: liste tudo que a IA já decide por você.</li><li>Procure no Office o ícone do Copilot — provavelmente já está disponível.</li><li>Experimente o "modo IA" de ferramentas que você já usa antes de migrar para outras.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confundir "tem botão automático" com "tem IA".</li><li>Não revisar o que a IA classifica como spam — perde mensagens importantes.</li></ul><h3>📌 Resumo final</h3><p>A IA já está em quase tudo que usamos. Reconhecê-la é o primeiro passo para usá-la com intenção.</p><h3>✏️ Exercício de fixação</h3><p>Faça uma lista de 10 ferramentas que você usa por dia. Ao lado de cada uma, marque um ✅ se ela já tem IA embutida.</p>', '', 2, 20, true, 'Identificar exemplos de IA presentes na rotina pessoal e profissional.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Nesta aula, vamos abrir os olhos. A IA não está só no futuro — ela está no seu celular, no seu e-mail, no GPS da sua viagem para casa. Vem comigo descobrir.', 'A IA já faz parte da rotina: GPS, e-mail, streaming, antifraude. Aprender a comandá-la diretamente é o próximo passo.', 'Mostrar 5 ferramentas do dia a dia (GPS, Netflix, Outlook, banco, fotos do celular) e destacar onde a IA atua em cada uma.', 'Tire prints de 3 lugares onde você encontra IA no seu trabalho. Compartilhe no grupo do curso.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os6', 'aula-1-2', 'Você Já Usa IA', 'A IA não está só em ferramentas avançadas. Ela aparece no celular, no banco, no e-mail, no mapa e nas plataformas que você usa todos os dias, muitas vezes sem perceber.', '/slides/m01/aula-1-2-01.png', 1),
  ('os7', 'aula-1-2', 'Antes Invisível, Agora Conversável', 'Antes a IA trabalhava escondida: filtrava spam, sugeria rotas e recomendava vídeos. Agora você pode conversar com ela diretamente e pedir ajuda para tarefas do trabalho.', '/slides/m01/aula-1-2-02.png', 2),
  ('os8', 'aula-1-2', 'Como Reconhecer IA', '1. A ferramenta sugere algo para você?
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q2', 'aula-1-2', 'Quiz: IA no Cotidiano')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p4', 'q2', 'Qual destes é exemplo de IA no cotidiano?', '[{"id":"a","texto":"Calculadora de bolso."},{"id":"b","texto":"Recomendação de séries da Netflix."},{"id":"c","texto":"Caneta esferográfica."},{"id":"d","texto":"Cafeteira com botão."}]'::jsonb, 'b', 1),
  ('p5', 'q2', 'O Copilot do Office é uma IA usada para...', '[{"id":"a","texto":"Substituir o usuário."},{"id":"b","texto":"Apenas corrigir ortografia."},{"id":"c","texto":"Auxiliar em escrita, análise e criação de conteúdo."},{"id":"d","texto":"Apenas formatar documentos."}]'::jsonb, 'c', 2),
  ('p6', 'q2', 'Por que reconhecer a IA ao redor importa?', '[{"id":"a","texto":"Para temê-la mais."},{"id":"b","texto":"Para usá-la com intenção e tirar mais valor dela."},{"id":"c","texto":"Para desativá-la em todas as ferramentas."},{"id":"d","texto":"Para ignorá-la."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-1-3', 'm01', 'IA vs Automação', 'Entenda as diferenças fundamentais entre automação tradicional e IA.', 'Quando usar automação simples e quando usar IA — e por quê.', '<h3>🎯 Objetivo da aula</h3><p>Saber escolher entre automação tradicional e IA dependendo do problema.</p><h3>📖 Explicação</h3><div><p>Automação tradicional é uma <strong>receita</strong>: "se chegar e-mail do fornecedor X, mova para a pasta Compras". Funciona perfeitamente quando o cenário é previsível.</p><p>IA é um <strong>cozinheiro que aprendeu mil receitas</strong>: você pede "organize meus e-mails por urgência" e ela decide caso a caso.</p><p>Use automação para regras estáveis. Use IA quando o contexto muda ou exige interpretação.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Automação: nota fiscal recebida → arquiva na pasta do mês.</li><li>IA: e-mails de clientes → classifica em urgentes, dúvidas, reclamações.</li><li>Híbrido: IA categoriza, automação envia para o departamento certo.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comece automatizando o que tem regra clara. IA depois.</li><li>Junte as duas: IA decide, automação executa.</li><li>Documente cada fluxo para revisar depois.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Usar IA onde uma fórmula simples resolveria.</li><li>Usar regra fixa onde o contexto muda toda hora.</li><li>Não medir o tempo economizado.</li></ul><h3>📌 Resumo final</h3><p>Automação resolve o previsível; IA resolve o ambíguo. O melhor resultado vem da combinação dos dois.</p><h3>✏️ Exercício de fixação</h3><p>Pegue um processo seu e divida em 3 colunas: passos automatizáveis, passos com IA, passos que continuam humanos.</p>', '', 3, 18, true, 'Distinguir automação tradicional de IA e decidir qual aplicar em cada situação.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Automação ou IA? Nem sempre a IA é a melhor escolha. Hoje você aprende a decidir entre elas.', 'Automação é regra fixa. IA é decisão adaptativa. Combine os dois para máxima eficiência.', 'Apresentar um fluxo de e-mails: parte fixa (filtro) vs parte interpretativa (urgência). Mostrar economia de tempo.', 'Escolha um processo do seu setor e desenhe um fluxograma indicando o que é regra fixa e o que precisa de interpretação.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os11', 'aula-1-3', 'IA Não É Automação Comum', 'Automação tradicional segue uma regra fixa. IA interpreta contexto e ajuda quando a situação muda. As duas são úteis, mas resolvem problemas diferentes.', '/slides/m01/aula-1-3-01.png', 1),
  ('os12', 'aula-1-3', 'Antes: Regra Fixa', 'Na automação comum, você define: "se chegar e-mail do fornecedor, mover para a pasta Compras". Ela funciona muito bem quando a regra é clara e repetida.', '/slides/m01/aula-1-3-02.png', 2),
  ('os13', 'aula-1-3', 'Com IA: Interpretação', 'Com IA, você pode pedir: "leia estes e-mails e separe por urgência". Ela compara linguagem, contexto e intenção. Depois, você revisa a classificação.', '/slides/m01/aula-1-3-03.png', 3),
  ('os14', 'aula-1-3', 'Escolha em 3 Perguntas', '1. A tarefa tem regra clara? Use automação
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q3', 'aula-1-3', 'Quiz: IA vs Automação')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p7', 'q3', 'Qual cenário é IDEAL para automação tradicional?', '[{"id":"a","texto":"Classificar emoções em mensagens de clientes."},{"id":"b","texto":"Mover toda nota fiscal recebida para uma pasta padrão."},{"id":"c","texto":"Resumir reuniões longas."},{"id":"d","texto":"Identificar sentimento em pesquisas."}]'::jsonb, 'b', 1),
  ('p8', 'q3', 'Qual cenário é IDEAL para IA?', '[{"id":"a","texto":"Renomear arquivos seguindo um padrão fixo."},{"id":"b","texto":"Calcular soma de uma coluna."},{"id":"c","texto":"Resumir reuniões de 1 hora em 5 linhas."},{"id":"d","texto":"Enviar e-mail toda segunda-feira às 9h."}]'::jsonb, 'c', 2),
  ('p9', 'q3', 'Qual é o modelo híbrido recomendado?', '[{"id":"a","texto":"IA decide e Automação executa."},{"id":"b","texto":"Automação decide e IA executa."},{"id":"c","texto":"Só usar IA."},{"id":"d","texto":"Só usar Automação."}]'::jsonb, 'a', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m02', 'M02 - Conceitos Essenciais', 'Machine Learning, Deep Learning, IA Generativa e LLMs.', 2, 5, true, '/covers/m02-conceitos-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-2-1', 'm02', 'Machine Learning', 'Entenda como as máquinas aprendem com dados.', 'O conceito por trás da IA: aprender com exemplos em vez de seguir regras.', '<h3>🎯 Objetivo da aula</h3><p>Entender o funcionamento básico do Machine Learning.</p><h3>📖 Explicação</h3><div><p>Machine Learning (ML) é o motor da IA moderna. Em vez de programar regras manualmente, você dá <strong>exemplos</strong> ao computador e ele descobre o padrão sozinho.</p><p>Existem 3 tipos principais:</p><ul><li><strong>Supervisionado:</strong> aprende com exemplos rotulados ("isso é spam, isso não é").</li><li><strong>Não-supervisionado:</strong> encontra padrões sem rótulos (agrupar clientes parecidos).</li><li><strong>Por reforço:</strong> aprende por tentativa e erro (jogos, robótica).</li></ul></div><h3>💼 Exemplos no escritório</h3><ul><li>Filtro de spam aprende com cada e-mail marcado por você.</li><li>Sistema de RH agrupa currículos similares automaticamente.</li><li>Assistente de vendas prevê fechamento com base em histórico.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Quanto mais dados de qualidade, melhor o resultado.</li><li>Dados ruins → resultado ruim. Sempre.</li><li>Você não precisa programar ML para usá-lo — basta usar ferramentas que já o aplicam.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar 100% em previsões sem entender de onde vieram.</li><li>Usar dados enviesados (que favorecem um grupo).</li></ul><h3>📌 Resumo final</h3><p>Machine Learning é o coração da IA: aprender com dados em vez de regras. Quanto mais bons exemplos, melhor.</p><h3>✏️ Exercício de fixação</h3><p>Pense em uma decisão repetitiva do seu trabalho. Se você desse 1000 exemplos a um computador, ele conseguiria prever a próxima?</p>', '', 1, 30, true, 'Compreender o que é Machine Learning e seus principais tipos.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Hoje começamos a entender o motor por trás da IA: o Machine Learning. Prepare-se — é mais simples do que parece.', 'ML é aprender com exemplos. Três tipos: supervisionado, não-supervisionado e reforço.', 'Animação: criança aprendendo a identificar frutas vs. computador aprendendo a identificar gatos. Mostrar os três tipos com exemplos.', 'Escolha uma tarefa do seu trabalho. Liste 10 exemplos que você usaria para "ensinar" um computador a fazê-la.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os16', 'aula-2-1', 'Machine Learning', 'Machine Learning é aprender com exemplos, não com regras escritas uma por uma. Em vez de programar cada situação, você mostra dados e a IA procura padrões para prever ou classificar novos casos.', '/slides/m02/aula-2-1-01.png', 1),
  ('os17', 'aula-2-1', 'Aprendizado Supervisionado', 'No aprendizado supervisionado, a IA aprende com exemplos que já têm resposta correta. É como ensinar com gabarito: "este e-mail é spam", "este não é". Depois ela tenta classificar novos e-mails.', '/slides/m02/aula-2-1-02.png', 2),
  ('os18', 'aula-2-1', 'Não-Supervisionado', 'No não-supervisionado, a IA recebe dados sem rótulos prontos e tenta encontrar grupos ou padrões escondidos. Um exemplo é agrupar clientes parecidos para entender comportamentos diferentes.', '/slides/m02/aula-2-1-03.png', 3),
  ('os19', 'aula-2-1', 'Aprendizado por Reforço', 'No aprendizado por reforço, a IA tenta uma ação, recebe recompensa ou erro e ajusta a próxima tentativa. Ela melhora praticando, como em jogos, robótica ou simulações de decisão.', '/slides/m02/aula-2-1-04.png', 4),
  ('os20', 'aula-2-1', 'Dado É Tudo', 'A qualidade dos dados define a qualidade do resultado. Dado bom ajuda a IA a acertar. Dado ruim, incompleto ou enviesado pode gerar previsões erradas e decisões injustas.', '/slides/m02/aula-2-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q4', 'aula-2-1', 'Quiz: Machine Learning')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p10', 'q4', 'O que é Machine Learning?', '[{"id":"a","texto":"Programação tradicional rápida."},{"id":"b","texto":"Sistemas que aprendem a partir de dados."},{"id":"c","texto":"Robôs físicos."},{"id":"d","texto":"Internet das coisas."}]'::jsonb, 'b', 1),
  ('p11', 'q4', 'Aprendizado supervisionado precisa de...', '[{"id":"a","texto":"Nenhum dado."},{"id":"b","texto":"Dados rotulados."},{"id":"c","texto":"Apenas reforços."},{"id":"d","texto":"Apenas regras."}]'::jsonb, 'b', 2),
  ('p12', 'q4', 'Qual é o maior risco do ML?', '[{"id":"a","texto":"Não ter internet."},{"id":"b","texto":"Usar dados enviesados que reproduzem injustiças."},{"id":"c","texto":"Consumir muita bateria."},{"id":"d","texto":"Não rodar offline."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-2-2', 'm02', 'Deep Learning e Redes Neurais', 'As redes neurais artificiais que potencializam a IA moderna.', 'O que está por trás de reconhecer imagens, traduzir línguas e gerar texto.', '<h3>🎯 Objetivo da aula</h3><p>Compreender, sem matemática, o que são redes neurais e Deep Learning.</p><h3>📖 Explicação</h3><div><p>Uma rede neural é inspirada no cérebro: camadas de "neurônios" artificiais que recebem informação, processam e passam adiante.</p><p>Deep Learning ("aprendizado profundo") é simplesmente uma rede neural com <strong>muitas camadas</strong>. Quanto mais camadas, mais sofisticados os padrões que ela consegue capturar.</p><p>É o que permite o ChatGPT entender contexto, o Google Translate traduzir nuances e o seu celular reconhecer seu rosto.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Reconhecimento facial do celular.</li><li>Tradução automática preservando o tom.</li><li>Geração de texto coerente em parágrafos longos.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Mais camadas ≠ sempre melhor. Custo computacional explode.</li><li>Modelos pré-treinados são acessíveis: você não precisa treinar do zero.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Achar que Deep Learning é "consciência".</li><li>Misturar Deep Learning com IA Geral (AGI).</li></ul><h3>📌 Resumo final</h3><p>Deep Learning é uma rede neural com muitas camadas. É a tecnologia por trás dos avanços recentes mais impressionantes.</p><h3>✏️ Exercício de fixação</h3><p>Em uma frase, explique para um colega o que é Deep Learning sem usar a palavra "neurônio".</p>', '', 2, 35, true, 'Entender o conceito de redes neurais e Deep Learning de forma intuitiva.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Redes neurais parecem complicadas — mas você vai sair desta aula explicando para a família.', 'Deep Learning são redes neurais com muitas camadas. É o motor do ChatGPT, da tradução automática e do reconhecimento facial.', 'Animação de neurônios artificiais em camadas processando uma imagem de gato. Mostrar como cada camada captura algo diferente.', 'Use o Google Translate em 3 frases idiomáticas em português → inglês. Avalie a tradução.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os21', 'aula-2-2', 'Rede Neural', 'Uma rede neural processa informação em camadas. A entrada passa por pequenos cálculos conectados e cada camada transforma um pouco o sinal até chegar a um resultado útil.', '/slides/m02/aula-2-2-01.png', 1),
  ('os22', 'aula-2-2', 'Deep = Muitas Camadas', 'Deep Learning é uma rede neural com muitas camadas. Quanto mais camadas, mais ricos podem ser os padrões capturados, como formas em imagens, nuances em textos e relações complexas.', '/slides/m02/aula-2-2-02.png', 2),
  ('os23', 'aula-2-2', 'Onde Aparece', 'Deep Learning aparece em ferramentas comuns: chatbots que entendem contexto, tradutores automáticos que preservam sentido e reconhecimento facial que identifica padrões em imagens.', '/slides/m02/aula-2-2-03.png', 3),
  ('os24', 'aula-2-2', 'Limites', 'Deep Learning não é consciência, não é AGI e não entende como uma pessoa. Ele calcula padrões de forma sofisticada e por isso ainda precisa de supervisão humana.', '/slides/m02/aula-2-2-04.png', 4),
  ('os25', 'aula-2-2', 'Modelos Pré-Treinados', 'Você não precisa treinar uma rede neural do zero. Hoje, modelos prontos aparecem em ferramentas que escrevem, traduzem, resumem e analisam documentos para uso no trabalho.', '/slides/m02/aula-2-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q5', 'aula-2-2', 'Quiz: Deep Learning e Redes Neurais')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p13', 'q5', 'O que torna o Deep Learning "deep"?', '[{"id":"a","texto":"Muito dado."},{"id":"b","texto":"Muitas camadas na rede neural."},{"id":"c","texto":"Muita memória RAM."},{"id":"d","texto":"Muita internet."}]'::jsonb, 'b', 1),
  ('p14', 'q5', 'Qual destes NÃO é Deep Learning?', '[{"id":"a","texto":"ChatGPT."},{"id":"b","texto":"Reconhecimento facial."},{"id":"c","texto":"Calculadora científica."},{"id":"d","texto":"Tradutor automático."}]'::jsonb, 'c', 2),
  ('p15', 'q5', 'Deep Learning é o mesmo que consciência artificial?', '[{"id":"a","texto":"Sim."},{"id":"b","texto":"Não — é apenas estatística sofisticada."},{"id":"c","texto":"Sim, em modelos grandes."},{"id":"d","texto":"Sim, quando online."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-2-3', 'm02', 'IA Generativa e LLMs', 'Os modelos que criaram o ChatGPT, Claude e Gemini.', 'O salto que trouxe a IA para o seu dia a dia: modelos que geram texto, imagem e código.', '<h3>🎯 Objetivo da aula</h3><p>Compreender a IA Generativa e os LLMs por trás do ChatGPT, Claude e Gemini.</p><h3>📖 Explicação</h3><div><p>IA Generativa é capaz de <strong>criar conteúdo novo</strong>: texto, imagem, código, áudio. Diferente de IAs anteriores que apenas classificavam ou previam.</p><p>LLMs (Large Language Models) foram treinados em bilhões de textos e aprenderam a prever a próxima palavra com tanta precisão que parecem entender o que escrevem.</p><p>São eles que dão vida ao <strong>ChatGPT</strong>, <strong>Claude</strong>, <strong>Gemini</strong> e <strong>Copilot</strong>.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Escrever um e-mail com tom adequado a partir de bullets.</li><li>Gerar uma imagem para a apresentação.</li><li>Resumir um PDF de 50 páginas em 1 página.</li></ul><h3>🪜 Passo a passo</h3><ol><li>Escolha uma ferramenta (ChatGPT, Claude ou Gemini).</li><li>Dê contexto claro: quem você é, o que precisa, para quem.</li><li>Refine com instruções específicas até o resultado servir.</li></ol><h3>💡 Dicas importantes</h3><ul><li>Quanto melhor o prompt, melhor a saída.</li><li>Trate a IA como um estagiário inteligente: precisa de instrução.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Achar que tudo é verdade — LLMs podem inventar (alucinação).</li><li>Não revisar antes de publicar.</li></ul><h3>📌 Resumo final</h3><p>LLMs são a tecnologia por trás dos chatbots modernos. Geram conteúdo novo, mas precisam de supervisão.</p><h3>✏️ Exercício de fixação</h3><p>Peça ao ChatGPT que escreva um e-mail para seu chefe pedindo 2 dias de folga, com tom respeitoso. Refine 2 vezes.</p>', '', 3, 40, true, 'Entender o que são LLMs (Modelos de Linguagem Grandes) e como diferem de IAs anteriores.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'A IA Generativa mudou tudo. Hoje você aprende por que ela é a estrela do momento.', 'LLMs geram texto novo a partir de bilhões de exemplos. ChatGPT, Claude e Gemini são todos LLMs.', 'Demo ao vivo: pedir um e-mail e um resumo. Mostrar refinamento de prompt em 3 iterações.', 'Escreva um e-mail profissional com a ajuda do ChatGPT em menos de 2 minutos.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os26', 'aula-2-3', 'IA Generativa', 'IA Generativa cria conteúdo novo, como texto, imagem, código e áudio. Ela não apenas classifica: ela produz uma primeira versão que você pode revisar e melhorar.', '/slides/m02/aula-2-3-01.png', 1),
  ('os27', 'aula-2-3', 'LLM', 'LLM significa Modelo de Linguagem Grande. Ele foi treinado com muitos textos, aprende padrões de linguagem e gera respostas prevendo a próxima palavra de forma muito precisa.', '/slides/m02/aula-2-3-02.png', 2),
  ('os28', 'aula-2-3', 'Ferramentas com LLM', 'ChatGPT, Claude, Gemini e Copilot usam modelos de linguagem para responder pedidos. A lógica é parecida: você dá contexto e instrução, recebe uma resposta e revisa antes de usar.', '/slides/m02/aula-2-3-03.png', 3),
  ('os29', 'aula-2-3', 'Cuidado: Alucinação', 'A IA pode inventar datas, números, links, leis ou nomes com aparência de certeza. Sempre verifique informações importantes em fonte confiável antes de publicar ou decidir.', '/slides/m02/aula-2-3-04.png', 4),
  ('os30', 'aula-2-3', 'Boa Prática', 'Trate a IA como um estagiário inteligente: dê contexto, explique a tarefa, peça o formato desejado e revise dados, tom e sentido antes de enviar ou compartilhar.', '/slides/m02/aula-2-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q6', 'aula-2-3', 'Quiz: IA Generativa e LLMs')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p16', 'q6', 'O que LLM significa?', '[{"id":"a","texto":"Last Language Module."},{"id":"b","texto":"Large Language Model."},{"id":"c","texto":"Light Learning Machine."},{"id":"d","texto":"Logic Language Mapper."}]'::jsonb, 'b', 1),
  ('p17', 'q6', 'Alucinação em LLM significa...', '[{"id":"a","texto":"Travar o computador."},{"id":"b","texto":"Inventar informação que parece correta."},{"id":"c","texto":"Recusar responder."},{"id":"d","texto":"Apagar dados."}]'::jsonb, 'b', 2),
  ('p18', 'q6', 'Qual destes NÃO é um LLM?', '[{"id":"a","texto":"ChatGPT."},{"id":"b","texto":"Claude."},{"id":"c","texto":"Excel."},{"id":"d","texto":"Gemini."}]'::jsonb, 'c', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m03', 'M03 - Ferramentas de IA', 'ChatGPT, Claude, Gemini, Copilot e Perplexity.', 3, 4, true, '/covers/m03-ferramentas-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-3-1', 'm03', 'ChatGPT na Prática', 'Como usar o ChatGPT para produtividade no trabalho.', 'Como usar o ChatGPT para produtividade no trabalho.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar o ChatGPT em tarefas reais do escritório.</p><h3>📖 Explicação</h3><div><p>O ChatGPT é a IA generativa mais popular do mundo, criada pela OpenAI. Funciona como um assistente de conversação capaz de escrever, resumir, traduzir, analisar e brainstormar. A versão gratuita já resolve 80% das demandas do escritório.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Resumir um e-mail longo em 3 bullets.</li><li>Gerar pauta de reunião a partir de objetivos.</li><li>Traduzir documentos com tom profissional.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use o modelo mais recente sempre que possível.</li><li>Salve seus prompts favoritos em um documento.</li><li>Crie uma "GPT customizado" para tarefas recorrentes.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Esquecer que ele não conhece dados internos da sua empresa.</li><li>Confiar em datas, números ou fatos sem checar.</li></ul><h3>📌 Resumo final</h3><p>ChatGPT é o canivete suíço da IA generativa para o escritório. Use com intenção e revise sempre.</p><h3>✏️ Exercício de fixação</h3><p>Use o ChatGPT para reescrever um e-mail seu em 3 tons: formal, amigável e direto.</p>', '', 1, 25, true, 'Aplicar o ChatGPT em tarefas reais do escritório.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'O ChatGPT virou rotina em milhões de escritórios. Nesta aula você aprende a tirar o máximo dele em minutos.', 'ChatGPT é o canivete suíço da IA generativa para o escritório. Use com intenção e revise sempre.', 'Apresentar ChatGPT na Prática: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Use o ChatGPT para reescrever um e-mail seu em 3 tons: formal, amigável e direto.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os31', 'aula-3-1', 'ChatGPT na Prática', 'O ChatGPT funciona como um assistente de conversa para tarefas de escritório. Você escreve um pedido, a IA organiza uma resposta e você revisa antes de usar.', '/slides/m03/aula-3-1-01.png', 1),
  ('os32', 'aula-3-1', 'O Que Ele Faz Bem', 'Ele ajuda muito em tarefas de texto: escrever e-mails, resumir mensagens longas, traduzir, analisar textos e gerar ideias. Comece por tarefas simples e revise sempre.', '/slides/m03/aula-3-1-02.png', 2),
  ('os33', 'aula-3-1', 'O Que Ele Não Sabe', 'O ChatGPT não acessa sozinho seus arquivos internos, dados da empresa ou números sem fonte. Se você não der contexto suficiente, ele pode adivinhar errado.', '/slides/m03/aula-3-1-03.png', 3),
  ('os34', 'aula-3-1', 'Truque de Ouro', 'Use a fórmula: contexto + papel + objetivo + restrições. Explique quem você é, o que precisa, como quer receber e quais limites a resposta deve respeitar.', '/slides/m03/aula-3-1-04.png', 4),
  ('os35', 'aula-3-1', 'Prática: 3 Tons', 'Cole um e-mail seu e peça três versões: formal, amigável e direta. Compare os tons, escolha o melhor para o público e ajuste antes de enviar.', '/slides/m03/aula-3-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q7', 'aula-3-1', 'Quiz: ChatGPT na Prática')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p19', 'q7', 'O ChatGPT é de qual empresa?', '[{"id":"a","texto":"Google."},{"id":"b","texto":"OpenAI."},{"id":"c","texto":"Microsoft."},{"id":"d","texto":"Anthropic."}]'::jsonb, 'b', 1),
  ('p20', 'q7', 'O que ChatGPT NÃO consegue acessar sozinho?', '[{"id":"a","texto":"Linguagem natural."},{"id":"b","texto":"Seus arquivos internos da empresa."},{"id":"c","texto":"Texto colado por você."},{"id":"d","texto":"Português brasileiro."}]'::jsonb, 'b', 2),
  ('p21', 'q7', 'O que sempre devemos fazer com a resposta do ChatGPT?', '[{"id":"a","texto":"Aceitar sem revisar."},{"id":"b","texto":"Compartilhar imediatamente."},{"id":"c","texto":"Revisar antes de enviar."},{"id":"d","texto":"Ignorar."}]'::jsonb, 'c', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-3-2', 'm03', 'Claude e Gemini', 'Os modelos da Anthropic e Google para o ambiente corporativo.', 'Os modelos da Anthropic e Google para o ambiente corporativo.', '<h3>🎯 Objetivo da aula</h3><p>Comparar Claude e Gemini com o ChatGPT e escolher a ferramenta certa.</p><h3>📖 Explicação</h3><div><p>Claude (Anthropic) é conhecido por respostas mais cuidadosas, longas e bem estruturadas. Gemini (Google) integra com o Workspace e tem acesso à internet em tempo real. Cada um brilha em um cenário.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Claude: análise longa de contrato.</li><li>Gemini: pesquisa rápida com dados atualizados.</li><li>ChatGPT: criação de conteúdo de marketing.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Teste o mesmo prompt nas 3 e compare.</li><li>Para textos longos, Claude costuma se sair melhor.</li><li>Para integração com Gmail/Docs, Gemini é nativo.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Achar que todos são iguais.</li><li>Não testar antes de pagar pela versão Pro.</li></ul><h3>📌 Resumo final</h3><p>Claude e Gemini são fortes alternativas ao ChatGPT. Cada um tem força em um cenário.</p><h3>✏️ Exercício de fixação</h3><p>Faça o mesmo prompt nos 3 (versões gratuitas) e compare estilo, profundidade e velocidade.</p>', '', 2, 25, true, 'Comparar Claude e Gemini com o ChatGPT e escolher a ferramenta certa.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'O ChatGPT não está sozinho. Hoje você conhece os concorrentes — e por que vale ter mais de um.', 'Claude e Gemini são fortes alternativas ao ChatGPT. Cada um tem força em um cenário.', 'Apresentar Claude e Gemini: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Faça o mesmo prompt nos 3 (versões gratuitas) e compare estilo, profundidade e velocidade.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os36', 'aula-3-2', 'Claude', 'Claude é uma alternativa forte para documentos longos, análises cuidadosas e respostas bem estruturadas. Use quando precisar de profundidade e organização.', '/slides/m03/aula-3-2-01.png', 1),
  ('os37', 'aula-3-2', 'Gemini', 'Gemini se destaca quando a tarefa envolve Google Workspace, pesquisa atualizada e integração com ferramentas como Gmail, Docs e Drive. Ainda assim, revise a resposta.', '/slides/m03/aula-3-2-02.png', 2),
  ('os38', 'aula-3-2', 'Quando Usar Cada Um', 'ChatGPT é versátil para criação e conversa. Claude costuma ajudar em análises longas. Gemini é útil para pesquisa atualizada e integração com o ambiente Google.', '/slides/m03/aula-3-2-03.png', 3),
  ('os39', 'aula-3-2', 'Compare o Mesmo Prompt', 'Teste a mesma tarefa em três ferramentas e compare estilo, profundidade e velocidade. Essa prática ajuda a escolher a melhor opção antes de pagar uma versão Pro.', '/slides/m03/aula-3-2-04.png', 4),
  ('os40', 'aula-3-2', 'Erro Comum', 'Não trate todas as ferramentas como iguais. Cada uma tem forças diferentes. Escolher pela tarefa reduz retrabalho e melhora a qualidade da revisão.', '/slides/m03/aula-3-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q8', 'aula-3-2', 'Quiz: Claude e Gemini')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p22', 'q8', 'Claude é desenvolvido por qual empresa?', '[{"id":"a","texto":"Google."},{"id":"b","texto":"Anthropic."},{"id":"c","texto":"OpenAI."},{"id":"d","texto":"Microsoft."}]'::jsonb, 'b', 1),
  ('p23', 'q8', 'Qual modelo integra nativamente com Google Docs?', '[{"id":"a","texto":"Claude."},{"id":"b","texto":"Gemini."},{"id":"c","texto":"ChatGPT."},{"id":"d","texto":"Perplexity."}]'::jsonb, 'b', 2),
  ('p24', 'q8', 'Qual é o melhor uso para Claude?', '[{"id":"a","texto":"Pesquisa rápida."},{"id":"b","texto":"Análises longas e bem estruturadas."},{"id":"c","texto":"Geração de imagem."},{"id":"d","texto":"Jogos."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-3-3', 'm03', 'Microsoft Copilot', 'O assistente de IA do Microsoft 365.', 'O assistente de IA do Microsoft 365.', '<h3>🎯 Objetivo da aula</h3><p>Usar o Copilot dentro de Word, Excel, Outlook e Teams.</p><h3>📖 Explicação</h3><div><p>Copilot é a IA da Microsoft integrada ao Office 365. Funciona dentro dos seus arquivos: lê o Word, analisa o Excel, resume o Teams. É a IA com mais contexto corporativo nativo.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>No Word: "reescreva este parágrafo de forma mais formal".</li><li>No Excel: "crie um gráfico que mostre a tendência destes dados".</li><li>No Teams: "resuma a reunião e liste os próximos passos".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Verifique se sua empresa tem licença antes de usar.</li><li>Funciona melhor quando o arquivo está bem estruturado.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Esperar que ele substitua você — ele assiste.</li><li>Não revisar as alterações.</li></ul><h3>📌 Resumo final</h3><p>Copilot é a IA mais integrada ao Office. Domine-o e seu Office vira um superpoder.</p><h3>✏️ Exercício de fixação</h3><p>No Word, peça ao Copilot para resumir um documento longo em 5 bullets.</p>', '', 3, 20, true, 'Usar o Copilot dentro de Word, Excel, Outlook e Teams.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Se você vive no Office, o Copilot é seu novo melhor amigo. Vem com a Microsoft, mora dentro dos seus arquivos.', 'Copilot é a IA mais integrada ao Office. Domine-o e seu Office vira um superpoder.', 'Apresentar Microsoft Copilot: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'No Word, peça ao Copilot para resumir um documento longo em 5 bullets.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os41', 'aula-3-3', 'Microsoft Copilot', 'Copilot é a IA integrada ao Microsoft 365. Ele trabalha dentro de arquivos e aplicativos como Word, Excel, Outlook e Teams, sempre com revisão humana.', '/slides/m03/aula-3-3-01.png', 1),
  ('os42', 'aula-3-3', 'Onde o Copilot Aparece', 'No Word ele revisa texto. No Excel analisa dados. No Outlook ajuda com e-mails. No Teams resume reuniões. No PowerPoint apoia apresentações.', '/slides/m03/aula-3-3-02.png', 2),
  ('os43', 'aula-3-3', 'Superpoder: Contexto', 'A força do Copilot é estar dentro do fluxo de trabalho. Ele pode usar o contexto do arquivo aberto, mas funciona melhor quando documentos e planilhas estão organizados.', '/slides/m03/aula-3-3-03.png', 3),
  ('os44', 'aula-3-3', 'Copilot em Ação', 'Peça ações claras: no Word, reescreva formal; no Excel, mostre tendência; no Teams, liste próximos passos. Depois confira se a sugestão faz sentido.', '/slides/m03/aula-3-3-04.png', 4),
  ('os45', 'aula-3-3', 'Copilot Não Substitui Você', 'Copilot assiste, mas você decide. Verifique dados, revise alterações, confirme permissões e aprove o conteúdo antes de enviar ou compartilhar.', '/slides/m03/aula-3-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q9', 'aula-3-3', 'Quiz: Microsoft Copilot')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p25', 'q9', 'Copilot é integrado a qual suite?', '[{"id":"a","texto":"Google Workspace."},{"id":"b","texto":"Microsoft 365."},{"id":"c","texto":"Adobe."},{"id":"d","texto":"Slack."}]'::jsonb, 'b', 1),
  ('p26', 'q9', 'Onde o Copilot NÃO está disponível?', '[{"id":"a","texto":"Word."},{"id":"b","texto":"Excel."},{"id":"c","texto":"Photoshop."},{"id":"d","texto":"Teams."}]'::jsonb, 'c', 2),
  ('p27', 'q9', 'O Copilot age sozinho ou em parceria?', '[{"id":"a","texto":"Sozinho."},{"id":"b","texto":"Em parceria com o usuário."},{"id":"c","texto":"Apenas como visualizador."},{"id":"d","texto":"Só em PDFs."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-3-4', 'm03', 'Perplexity AI', 'A IA que pesquisa com fontes citadas.', 'A IA que pesquisa com fontes citadas.', '<h3>🎯 Objetivo da aula</h3><p>Usar Perplexity para pesquisas confiáveis com referência.</p><h3>📖 Explicação</h3><div><p>Perplexity é uma IA de pesquisa: ela responde sua pergunta E mostra as fontes. Ideal para quando você precisa de informação atual e confiável.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Pesquisa de mercado com fontes.</li><li>Resumo de notícias do setor.</li><li>Levantamento de concorrentes.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Sempre clique nas fontes — IA pode interpretar errado.</li><li>Use no Pro mode para respostas mais profundas.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar no resumo sem ler as fontes.</li></ul><h3>📌 Resumo final</h3><p>Perplexity é o Google + ChatGPT. Pesquisa com IA mostrando referência.</p><h3>✏️ Exercício de fixação</h3><p>Pesquise "tendências de IA para escritório em 2025" no Perplexity e verifique 3 fontes.</p>', '', 4, 15, true, 'Usar Perplexity para pesquisas confiáveis com referência.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Para pesquisar com confiança, Perplexity entrega o que o ChatGPT não pode: fontes citadas.', 'Perplexity é o Google + ChatGPT. Pesquisa com IA mostrando referência.', 'Apresentar Perplexity AI: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Pesquise "tendências de IA para escritório em 2025" no Perplexity e verifique 3 fontes.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os46', 'aula-3-4', 'Perplexity AI', 'Perplexity é uma IA de pesquisa com fontes citadas. Ela ajuda a transformar uma pergunta em resposta organizada, mas as fontes precisam ser abertas e verificadas.', '/slides/m03/aula-3-4-01.png', 1),
  ('os47', 'aula-3-4', 'Quando Usar Perplexity', 'Use Perplexity para pesquisa de mercado, notícias do setor e levantamento de concorrentes. Ele é útil quando você precisa de informação atual e verificável.', '/slides/m03/aula-3-4-02.png', 2),
  ('os48', 'aula-3-4', 'Sempre Confira as Fontes', 'Antes de citar uma resposta, clique no link, veja a data, confirme a origem e compare com outra fonte. Não use apenas o resumo gerado pela IA.', '/slides/m03/aula-3-4-03.png', 3),
  ('os49', 'aula-3-4', 'Busca + Conversa', 'A busca tradicional entrega muitos links. A IA de pesquisa organiza um resumo com fontes. Isso acelera o trabalho, mas a validação continua sendo sua.', '/slides/m03/aula-3-4-04.png', 4),
  ('os50', 'aula-3-4', 'Prática com Fontes', 'Pesquise uma tendência, abra três fontes e anote o que foi confirmado. Uma boa pesquisa termina com evidência verificável, não só com uma resposta bonita.', '/slides/m03/aula-3-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q10', 'aula-3-4', 'Quiz: Perplexity AI')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p28', 'q10', 'O que diferencia Perplexity?', '[{"id":"a","texto":"Gera imagens."},{"id":"b","texto":"Mostra fontes citadas."},{"id":"c","texto":"Roda offline."},{"id":"d","texto":"Só responde em inglês."}]'::jsonb, 'b', 1),
  ('p29', 'q10', 'Qual ação é obrigatória antes de citar uma resposta do Perplexity?', '[{"id":"a","texto":"Compartilhar nas redes."},{"id":"b","texto":"Verificar as fontes."},{"id":"c","texto":"Pagar o Pro."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'b', 2),
  ('p30', 'q10', 'Perplexity é melhor para...', '[{"id":"a","texto":"Brincadeira casual."},{"id":"b","texto":"Pesquisa com referências."},{"id":"c","texto":"Gerar planilhas."},{"id":"d","texto":"Editar vídeo."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m04', 'M04 - Segurança e LGPD', 'Dados sensíveis, listas verde e vermelha, boas práticas.', 4, 3, true, '/covers/m04-seguranca-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-4-1', 'm04', 'LGPD e IA', 'O que a LGPD diz sobre uso de IA com dados pessoais.', 'O que a LGPD diz sobre uso de IA com dados pessoais.', '<h3>🎯 Objetivo da aula</h3><p>Entender as regras da LGPD aplicadas ao uso de IA.</p><h3>📖 Explicação</h3><div><p>A Lei Geral de Proteção de Dados (LGPD) regula como dados pessoais podem ser coletados, tratados e compartilhados. Quando você usa IA, frequentemente está enviando dados a terceiros — e isso exige cuidado.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>NÃO cole CPF de cliente no ChatGPT.</li><li>NÃO envie planilha de salários sem anonimizar.</li><li>PODE colar texto sem dados pessoais.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Anonimize antes de enviar (substitua nomes por "Cliente A").</li><li>Use ferramentas corporativas com contrato (Copilot empresarial, ChatGPT Enterprise).</li><li>Documente decisões automatizadas — a LGPD exige rastreabilidade.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Colar contrato com dados de cliente em IA pública.</li><li>Achar que "ferramenta gratuita" significa "sem responsabilidade".</li></ul><h3>📌 Resumo final</h3><p>LGPD vale também para IA. Dado pessoal precisa de cuidado, mesmo (ou principalmente) ao usar IA.</p><h3>✏️ Exercício de fixação</h3><p>Liste 3 tipos de dado que você manipula e classifique: pode colar / precisa anonimizar / nunca enviar.</p>', '', 1, 25, true, 'Entender as regras da LGPD aplicadas ao uso de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'LGPD e IA caminham juntas. Aprender as regras protege você, o cliente e a empresa.', 'LGPD vale também para IA. Dado pessoal precisa de cuidado, mesmo (ou principalmente) ao usar IA.', 'Apresentar LGPD e IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Liste 3 tipos de dado que você manipula e classifique: pode colar / precisa anonimizar / nunca enviar.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os51', 'aula-4-1', 'LGPD em 1 Frase', 'A LGPD é a lei que protege dados pessoais no Brasil. Se uma informação identifica uma pessoa, como nome, CPF, e-mail ou telefone, ela exige cuidado antes de ser usada com IA.', '/slides/m04/aula-4-1-01.png', 1),
  ('os52', 'aula-4-1', 'IA Também Envolve Dados', 'Quando você cola informação em uma ferramenta de IA, pode estar enviando dados para terceiros. Usar IA não elimina responsabilidade sobre clientes, funcionários e contratos.', '/slides/m04/aula-4-1-02.png', 2),
  ('os53', 'aula-4-1', 'Regra de Ouro', 'Dado pessoal em IA externa exige base legal, necessidade e cuidado. Antes de enviar, pergunte: tem autorização, é necessário, posso anonimizar e a ferramenta é corporativa?', '/slides/m04/aula-4-1-03.png', 3),
  ('os54', 'aula-4-1', 'Anonimize Antes', 'Antes de usar IA, troque dados reais por exemplos fictícios. Cliente A, Funcionário B e Empresa X ajudam a preservar o contexto sem expor pessoas reais.', '/slides/m04/aula-4-1-04.png', 4),
  ('os55', 'aula-4-1', 'Prática LGPD', 'Liste os dados que você usa no trabalho, classifique o risco e escolha a ação: pode usar, precisa anonimizar ou nunca deve enviar. Segurança começa antes do prompt.', '/slides/m04/aula-4-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q11', 'aula-4-1', 'Quiz: LGPD e IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p31', 'q11', 'O que a LGPD protege?', '[{"id":"a","texto":"Marcas."},{"id":"b","texto":"Dados pessoais."},{"id":"c","texto":"Senhas Wi-Fi."},{"id":"d","texto":"Logotipos."}]'::jsonb, 'b', 1),
  ('p32', 'q11', 'Posso colar CPF de cliente no ChatGPT gratuito?', '[{"id":"a","texto":"Sim, sempre."},{"id":"b","texto":"Não — viola LGPD."},{"id":"c","texto":"Sim, se for só um."},{"id":"d","texto":"Sim, à noite."}]'::jsonb, 'b', 2),
  ('p33', 'q11', 'Qual é uma boa prática?', '[{"id":"a","texto":"Anonimizar antes de enviar."},{"id":"b","texto":"Enviar tudo bruto."},{"id":"c","texto":"Confiar na ferramenta."},{"id":"d","texto":"Ignorar a LGPD."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-4-2', 'm04', 'Listas Verde e Vermelha', 'O que você pode e o que não pode colar em IAs externas.', 'O que você pode e o que não pode colar em IAs externas.', '<h3>🎯 Objetivo da aula</h3><p>Memorizar a lista verde (livre) e vermelha (proibido) de dados.</p><h3>📖 Explicação</h3><div><p>Para acelerar decisões no dia a dia, use uma régua simples: lista verde = pode; lista vermelha = nunca. Em dúvida, classifique como vermelha.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Verde: texto público, dúvida conceitual, modelo de e-mail.</li><li>Vermelha: CPF, contrato com dados, salário, segredo de cliente.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Imprima a régua e cole no monitor.</li><li>Tem dúvida? Trate como vermelha.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Misturar as duas: parte verde + 1 dado vermelho.</li></ul><h3>📌 Resumo final</h3><p>Régua simples acelera decisão e protege você.</p><h3>✏️ Exercício de fixação</h3><p>Crie sua régua personalizada para a sua área de trabalho.</p>', '', 2, 20, true, 'Memorizar a lista verde (livre) e vermelha (proibido) de dados.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Duas listas. Memorize-as. Use-as. Sua reputação agradece.', 'Régua simples acelera decisão e protege você.', 'Apresentar Listas Verde e Vermelha: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie sua régua personalizada para a sua área de trabalho.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os56', 'aula-4-2', 'Lista Verde', 'A lista verde reúne informações de baixo risco: texto público, dúvida conceitual, modelo sem dados, template fictício e checklist genérico. Sem dados reais, o risco cai muito.', '/slides/m04/aula-4-2-01.png', 1),
  ('os57', 'aula-4-2', 'Lista Vermelha', 'A lista vermelha reúne dados que nunca entram em IA pública: CPF, RG, salário, dados bancários, dados de saúde, contratos com cliente e segredos da empresa.', '/slides/m04/aula-4-2-02.png', 2),
  ('os58', 'aula-4-2', 'Em Dúvida', 'Quando você não tiver certeza de que o conteúdo é seguro, trate como vermelho e não envie. A pressa de usar IA não vale um vazamento de dados.', '/slides/m04/aula-4-2-03.png', 3),
  ('os59', 'aula-4-2', 'Erro: Misturar Dados', 'Um documento quase seguro deixa de ser seguro se tiver um único dado sensível. Um CPF, nome real ou valor confidencial contamina todo o conteúdo.', '/slides/m04/aula-4-2-04.png', 4),
  ('os60', 'aula-4-2', 'Régua Rápida', 'Use três zonas de decisão: verde pode usar, amarelo anonimiza antes, vermelho nunca envia. Em dúvida, suba o nível de proteção.', '/slides/m04/aula-4-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q12', 'aula-4-2', 'Quiz: Listas Verde e Vermelha')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p34', 'q12', 'Modelo de e-mail genérico, sem nomes: que lista?', '[{"id":"a","texto":"Verde."},{"id":"b","texto":"Vermelha."},{"id":"c","texto":"Amarela."},{"id":"d","texto":"Nenhuma."}]'::jsonb, 'a', 1),
  ('p35', 'q12', 'Contrato com nome do cliente: que lista?', '[{"id":"a","texto":"Verde."},{"id":"b","texto":"Vermelha."},{"id":"c","texto":"Amarela."},{"id":"d","texto":"Azul."}]'::jsonb, 'b', 2),
  ('p36', 'q12', 'Em dúvida, tratar como?', '[{"id":"a","texto":"Verde."},{"id":"b","texto":"Vermelha."},{"id":"c","texto":"Cinza."},{"id":"d","texto":"Roxa."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-4-3', 'm04', 'Boas Práticas de Segurança', 'Senha forte, 2FA, ferramentas corporativas e revisão humana.', 'Senha forte, 2FA, ferramentas corporativas e revisão humana.', '<h3>🎯 Objetivo da aula</h3><p>Adotar práticas de segurança ao usar IA no trabalho.</p><h3>📖 Explicação</h3><div><p>Além da LGPD, é essencial proteger sua conta e os fluxos onde a IA atua. Senha forte, autenticação em dois fatores, contas separadas para uso pessoal e corporativo.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Usar gerenciador de senhas.</li><li>Ativar 2FA em todas as contas de IA.</li><li>Não compartilhar conta com colegas.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Revise periodicamente o histórico das suas IAs.</li><li>Desative o uso de seus dados para treino quando possível.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Usar a mesma senha em todas as IAs.</li><li>Compartilhar a conta da empresa.</li></ul><h3>📌 Resumo final</h3><p>Segurança é hábito. Senha forte, 2FA, conta separada — e revisão constante.</p><h3>✏️ Exercício de fixação</h3><p>Ative 2FA nas suas contas de IA hoje.</p>', '', 3, 20, true, 'Adotar práticas de segurança ao usar IA no trabalho.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Boas práticas evitam dores de cabeça. Hoje é dia de blindar suas contas.', 'Segurança é hábito. Senha forte, 2FA, conta separada — e revisão constante.', 'Apresentar Boas Práticas de Segurança: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Ative 2FA nas suas contas de IA hoje.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os61', 'aula-4-3', '4 Práticas de Ouro', 'Segurança é hábito: use senha forte, ative 2FA, separe conta pessoal da corporativa e faça revisão periódica dos acessos e históricos.', '/slides/m04/aula-4-3-01.png', 1),
  ('os62', 'aula-4-3', 'Ative 2FA', '2FA adiciona uma segunda etapa de proteção. Mesmo que a senha vaze, o código no celular ou aplicativo autenticador ajuda a impedir acesso indevido.', '/slides/m04/aula-4-3-02.png', 2),
  ('os63', 'aula-4-3', 'Contas Separadas', 'Separe uso pessoal e corporativo. Conta pessoal serve para estudos e exemplos fictícios. Conta corporativa deve seguir ferramentas aprovadas e políticas internas.', '/slides/m04/aula-4-3-03.png', 3),
  ('os64', 'aula-4-3', 'Dados Para Treino', 'Quando possível, abra as configurações de privacidade e desative o uso dos seus dados para treino de modelo. Confirme sempre a política da empresa.', '/slides/m04/aula-4-3-04.png', 4),
  ('os65', 'aula-4-3', 'Revisão Periódica', 'Todo mês, revise histórico, apague conversas sensíveis, cheque permissões e atualize senhas quando necessário. Proteção melhora quando vira rotina.', '/slides/m04/aula-4-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q13', 'aula-4-3', 'Quiz: Boas Práticas de Segurança')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p37', 'q13', '2FA significa...', '[{"id":"a","texto":"Two Factor Authentication."},{"id":"b","texto":"Fast File Access."},{"id":"c","texto":"Free For All."},{"id":"d","texto":"Full Force Auth."}]'::jsonb, 'a', 1),
  ('p38', 'q13', 'Compartilhar conta corporativa é boa prática?', '[{"id":"a","texto":"Sim."},{"id":"b","texto":"Não."},{"id":"c","texto":"Sim, se forem 2."},{"id":"d","texto":"Sim, no fim do mês."}]'::jsonb, 'b', 2),
  ('p39', 'q13', 'O que reduz risco?', '[{"id":"a","texto":"Senha igual em tudo."},{"id":"b","texto":"2FA ativo."},{"id":"c","texto":"Login automático."},{"id":"d","texto":"Nada."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m05', 'M05 - Engenharia de Prompt', 'Método CIFE, estrutura de prompts e exemplos práticos.', 5, 5, true, '/covers/m05-prompt-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-5-1', 'm05', 'O que é Prompt', 'A arte de pedir bem para a IA.', 'A arte de pedir bem para a IA.', '<h3>🎯 Objetivo da aula</h3><p>Entender o que é um prompt e por que ele determina o resultado.</p><h3>📖 Explicação</h3><div><p>Prompt é a instrução que você dá à IA. Como em qualquer relação, instrução clara = resultado claro. Um prompt ruim culpa a ferramenta; um prompt bom revela todo o seu potencial.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Prompt ruim: "escreva um e-mail".</li><li>Prompt bom: "escreva um e-mail formal de cobrança ao fornecedor X sobre atraso de 5 dias na entrega do pedido 1234, tom firme mas cordial".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Quanto mais contexto, melhor.</li><li>Especifique tom, tamanho, público e formato.</li><li>Itere: refine até chegar onde quer.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Esperar que a IA "adivinhe".</li><li>Pedir tudo em uma única frase genérica.</li></ul><h3>📌 Resumo final</h3><p>Prompt é instrução. Boa instrução, bom resultado.</p><h3>✏️ Exercício de fixação</h3><p>Pegue um prompt seu de 1 linha e transforme em 5 linhas com contexto.</p>', '', 1, 20, true, 'Entender o que é um prompt e por que ele determina o resultado.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Aprender prompt é aprender a se comunicar com uma nova categoria de assistente.', 'Prompt é instrução. Boa instrução, bom resultado.', 'Apresentar O que é Prompt: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Pegue um prompt seu de 1 linha e transforme em 5 linhas com contexto.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os66', 'aula-5-1', 'O Que É Prompt', 'Prompt é a instrução que você dá para a IA. Você escreve um pedido, a IA interpreta, responde e você revisa antes de usar. Boa instrução gera melhor resposta.', '/slides/m05/aula-5-1-01.png', 1),
  ('os67', 'aula-5-1', 'Prompt Ruim x Prompt Bom', 'Um pedido vago, como "escreva um e-mail", gera resposta genérica. Um pedido com objetivo, destinatário, tom e contexto produz um resultado muito mais útil.', '/slides/m05/aula-5-1-02.png', 2),
  ('os68', 'aula-5-1', 'Receita de Prompt', 'Use a receita: contexto, papel, objetivo, restrições e formato. Diga quem você é, qual papel a IA deve assumir, o que precisa e como quer receber.', '/slides/m05/aula-5-1-03.png', 3),
  ('os69', 'aula-5-1', 'Itere e Refine', 'O primeiro prompt raramente é o ideal. Faça o pedido, leia a resposta, peça ajustes e aprove a versão final apenas depois de revisar.', '/slides/m05/aula-5-1-04.png', 4),
  ('os70', 'aula-5-1', 'Prática: Melhore Seu Prompt', 'Pegue um pedido de uma linha e transforme em uma instrução completa: cargo, tema, público, formato e limites. Pedido vago vira comando claro.', '/slides/m05/aula-5-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q14', 'aula-5-1', 'Quiz: O que é Prompt')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p40', 'q14', 'Prompt é...', '[{"id":"a","texto":"A IA."},{"id":"b","texto":"A instrução que você dá à IA."},{"id":"c","texto":"O computador."},{"id":"d","texto":"A internet."}]'::jsonb, 'b', 1),
  ('p41', 'q14', 'Bom prompt tem...', '[{"id":"a","texto":"1 palavra."},{"id":"b","texto":"Contexto, papel, objetivo, formato."},{"id":"c","texto":"Apenas emojis."},{"id":"d","texto":"Só sim ou não."}]'::jsonb, 'b', 2),
  ('p42', 'q14', 'O que fazer se o primeiro resultado não serve?', '[{"id":"a","texto":"Desistir."},{"id":"b","texto":"Iterar e refinar."},{"id":"c","texto":"Trocar de ferramenta."},{"id":"d","texto":"Reiniciar o PC."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-5-2', 'm05', 'Método CIFE', 'Contexto, Instrução, Formato, Exemplos — a fórmula universal.', 'Contexto, Instrução, Formato, Exemplos — a fórmula universal.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar o método CIFE para construir prompts profissionais.</p><h3>📖 Explicação</h3><div><p>CIFE é uma estrutura para escrever prompts: Contexto (quem você é e o cenário), Instrução (o que quer), Formato (como entregar), Exemplos (modelos quando possível). Aplicar essa receita melhora o resultado em 80% dos casos.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>C: "Sou analista de RH de uma empresa de 200 pessoas." I: "Escreva um e-mail de feedback positivo para um colaborador." F: "3 parágrafos curtos." E: "Modelo: começar com a conquista, dar exemplo concreto, fechar com incentivo."</li></ul><h3>💡 Dicas importantes</h3><ul><li>Sempre comece pelo contexto.</li><li>Use exemplos sempre que possível — é o que mais melhora a saída.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Pular o contexto.</li><li>Não especificar formato.</li></ul><h3>📌 Resumo final</h3><p>CIFE: Contexto + Instrução + Formato + Exemplos. Aplique sempre.</p><h3>✏️ Exercício de fixação</h3><p>Reescreva um prompt seu seguindo CIFE rigorosamente.</p>', '', 2, 25, true, 'Aplicar o método CIFE para construir prompts profissionais.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Quatro letras. Uma fórmula. Resultado profissional. Vem aprender o CIFE.', 'CIFE: Contexto + Instrução + Formato + Exemplos. Aplique sempre.', 'Apresentar Método CIFE: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Reescreva um prompt seu seguindo CIFE rigorosamente.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os71', 'aula-5-2', 'Método CIFE', 'CIFE é uma estrutura simples para escrever prompts profissionais: Contexto, Instrução, Formato e Exemplos. Quatro partes reduzem ambiguidade.', '/slides/m05/aula-5-2-01.png', 1),
  ('os72', 'aula-5-2', 'C de Contexto', 'Contexto responde: quem sou, qual é a situação, para quem é e qual objetivo. Sem contexto, a IA tenta adivinhar o cenário.', '/slides/m05/aula-5-2-02.png', 2),
  ('os73', 'aula-5-2', 'I de Instrução', 'Instrução é o comando claro. Use verbos de ação como crie, resuma, liste, revise, compare e transforme. Evite pedidos vagos como "fale sobre".', '/slides/m05/aula-5-2-03.png', 3),
  ('os74', 'aula-5-2', 'F de Formato', 'Formato define como a resposta deve chegar: tabela, lista numerada, e-mail formal, três parágrafos ou checklist. Diga como quer receber.', '/slides/m05/aula-5-2-04.png', 4),
  ('os75', 'aula-5-2', 'E de Exemplos', 'Exemplos calibram a IA. Quando você mostra um modelo esperado, a resposta fica mais alinhada ao padrão, ao tom e à estrutura que deseja.', '/slides/m05/aula-5-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q15', 'aula-5-2', 'Quiz: Método CIFE')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p43', 'q15', 'O que CIFE significa?', '[{"id":"a","texto":"Contexto, Instrução, Formato, Exemplos."},{"id":"b","texto":"Código, Imagem, Fórmula, Email."},{"id":"c","texto":"Cor, Item, Fonte, Estilo."},{"id":"d","texto":"Cliente, Item, Fatura, Entrega."}]'::jsonb, 'a', 1),
  ('p44', 'q15', 'Qual letra do CIFE costuma ser pulada?', '[{"id":"a","texto":"I."},{"id":"b","texto":"C."},{"id":"c","texto":"F."},{"id":"d","texto":"E."}]'::jsonb, 'b', 2),
  ('p45', 'q15', 'O que mais eleva o resultado?', '[{"id":"a","texto":"Emojis."},{"id":"b","texto":"Exemplos."},{"id":"c","texto":"Tamanho do prompt."},{"id":"d","texto":"Velocidade de digitação."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-5-3', 'm05', 'Estrutura de Prompts Eficazes', 'Templates, papéis e restrições para resultados consistentes.', 'Templates, papéis e restrições para resultados consistentes.', '<h3>🎯 Objetivo da aula</h3><p>Construir templates de prompt reutilizáveis.</p><h3>📖 Explicação</h3><div><p>Prompts eficazes têm estrutura repetível. Defina papel ("você é um redator sênior"), público ("para um diretor financeiro"), objetivo, restrições ("máx. 200 palavras, sem jargão") e formato de saída. Salve isso como template.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Template de "responder cliente bravo".</li><li>Template de "resumir reunião".</li><li>Template de "criar pauta".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Crie uma biblioteca de templates por tarefa.</li><li>Use placeholders [ASSUNTO] [TOM] para reaproveitar.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Refazer o mesmo prompt do zero toda vez.</li><li>Não medir o que funciona.</li></ul><h3>📌 Resumo final</h3><p>Prompt = template + variáveis. Crie uma biblioteca.</p><h3>✏️ Exercício de fixação</h3><p>Crie 3 templates para tarefas recorrentes suas.</p>', '', 3, 25, true, 'Construir templates de prompt reutilizáveis.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Quem usa template, ganha tempo todo dia. Vem montar a sua biblioteca.', 'Prompt = template + variáveis. Crie uma biblioteca.', 'Apresentar Estrutura de Prompts Eficazes: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie 3 templates para tarefas recorrentes suas.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os76', 'aula-5-3', 'Prompt Eficaz Tem Estrutura', 'Um prompt eficaz combina papel, público, objetivo, restrições e formato. Essa estrutura deixa o resultado mais previsível e reduz retrabalho.', '/slides/m05/aula-5-3-01.png', 1),
  ('os77', 'aula-5-3', 'Template Reutilizável', 'Transforme bons prompts em moldes com lacunas. Preencha papel, entrega, público, tom e formato para criar novos pedidos rapidamente.', '/slides/m05/aula-5-3-02.png', 2),
  ('os78', 'aula-5-3', 'Use Placeholders', 'Placeholders como [ASSUNTO], [TOM], [CLIENTE], [PRAZO] e [FORMATO] permitem trocar só as partes variáveis e reaproveitar o mesmo prompt.', '/slides/m05/aula-5-3-03.png', 3),
  ('os79', 'aula-5-3', 'Biblioteca de Prompts', 'Organize seus melhores prompts por categoria: e-mails, reuniões, planilhas, atendimento e relatórios. Uma biblioteca compartilhada aumenta a produtividade da equipe.', '/slides/m05/aula-5-3-04.png', 4),
  ('os80', 'aula-5-3', 'Meça o Que Funciona', 'Avalie cada prompt pelo resultado, tempo economizado, qualidade e revisão necessária. Teste, salve o melhor e reutilize o que já funcionou.', '/slides/m05/aula-5-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q16', 'aula-5-3', 'Quiz: Estrutura de Prompts Eficazes')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p46', 'q16', 'O que é template de prompt?', '[{"id":"a","texto":"Um arquivo .doc."},{"id":"b","texto":"Um molde reutilizável com placeholders."},{"id":"c","texto":"A IA."},{"id":"d","texto":"Um software."}]'::jsonb, 'b', 1),
  ('p47', 'q16', 'Por que usar templates?', '[{"id":"a","texto":"Ganha tempo e mantém qualidade."},{"id":"b","texto":"É obrigatório."},{"id":"c","texto":"A IA exige."},{"id":"d","texto":"Para impressionar."}]'::jsonb, 'a', 2),
  ('p48', 'q16', 'Placeholder serve para...', '[{"id":"a","texto":"Decorar."},{"id":"b","texto":"Substituir por valor variável."},{"id":"c","texto":"Travar a IA."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-5-4', 'm05', 'Prompts para Escritório', 'Coletânea de prompts prontos para o dia a dia.', 'Coletânea de prompts prontos para o dia a dia.', '<h3>🎯 Objetivo da aula</h3><p>Conhecer prompts validados para tarefas comuns no escritório.</p><h3>📖 Explicação</h3><div><p>Uma boa biblioteca de prompts é um ativo. Esta aula traz exemplos prontos para e-mail, reunião, planilha e atendimento.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>E-mail: "Reescreva o e-mail abaixo no tom [formal/amigável], máx 150 palavras, sem jargões".</li><li>Reunião: "Resuma a transcrição abaixo em decisões, pendências e responsáveis".</li><li>Planilha: "Sugira fórmula para calcular X na coluna Y considerando Z".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comece pela tarefa mais repetitiva sua.</li><li>Compartilhe a biblioteca com a equipe.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Não adaptar o template ao contexto.</li></ul><h3>📌 Resumo final</h3><p>Biblioteca pronta = produtividade pronta.</p><h3>✏️ Exercício de fixação</h3><p>Adapte 5 prompts desta aula ao seu cargo.</p>', '', 4, 25, true, 'Conhecer prompts validados para tarefas comuns no escritório.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Hoje é dia de roubar bons prompts — e fazer eles trabalharem por você.', 'Biblioteca pronta = produtividade pronta.', 'Apresentar Prompts para Escritório: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Adapte 5 prompts desta aula ao seu cargo.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os81', 'aula-5-4', 'Prompts Para Escritório', 'Comece pelas tarefas mais repetitivas: e-mail, reunião, planilha e atendimento. Cada tarefa pode ter um prompt modelo para acelerar o trabalho.', '/slides/m05/aula-5-4-01.png', 1),
  ('os82', 'aula-5-4', 'Prompt Para E-mail', 'Um bom prompt de e-mail define objetivo, destinatário, tom, tamanho e ação final. Defina o tom antes de enviar e revise nomes, dados e pedidos.', '/slides/m05/aula-5-4-02.png', 2),
  ('os83', 'aula-5-4', 'Prompt Para Reunião', 'Cole anotações ou transcrição e peça que a IA organize decisões, pendências, responsáveis e prazos. Reunião boa termina com próximos passos claros.', '/slides/m05/aula-5-4-03.png', 3),
  ('os84', 'aula-5-4', 'Prompt Para Planilha', 'Descreva o cálculo, explique as colunas, informe onde a fórmula será usada e peça explicação. A IA cria melhor quando entende a planilha.', '/slides/m05/aula-5-4-04.png', 4),
  ('os85', 'aula-5-4', 'Adapte ao Seu Cargo', 'Escolha cinco prompts, troque para sua área e salve na biblioteca. Prompt bom fica ainda melhor quando vira parte do seu jeito de trabalhar.', '/slides/m05/aula-5-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q17', 'aula-5-4', 'Quiz: Prompts para Escritório')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p49', 'q17', 'O que é uma biblioteca de prompts?', '[{"id":"a","texto":"Sala física."},{"id":"b","texto":"Coleção de prompts prontos."},{"id":"c","texto":"Site da OpenAI."},{"id":"d","texto":"Livro de IA."}]'::jsonb, 'b', 1),
  ('p50', 'q17', 'Quem deve manter a biblioteca?', '[{"id":"a","texto":"Só o gestor."},{"id":"b","texto":"Toda a equipe."},{"id":"c","texto":"Só TI."},{"id":"d","texto":"Só estagiários."}]'::jsonb, 'b', 2),
  ('p51', 'q17', 'O que falta em um template genérico?', '[{"id":"a","texto":"Cor."},{"id":"b","texto":"Contexto específico do usuário."},{"id":"c","texto":"Imagem."},{"id":"d","texto":"Senha."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m06', 'M06 - Técnicas Avançadas', 'Personas, cadeias de prompts, análise e criação.', 6, 5, true, '/covers/m06-tecnicas-avancadas-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-6-1', 'm06', 'Personas e Papéis', 'Diga à IA quem ela deve "ser" para responder melhor.', 'Diga à IA quem ela deve "ser" para responder melhor.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar a técnica de persona para refinar respostas da IA.</p><h3>📖 Explicação</h3><div><p>Quando você dá um papel à IA ("você é um consultor sênior", "você é um redator publicitário"), a saída muda de qualidade. Isso direciona vocabulário, tom e foco.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>"Você é um auditor: revise este processo".</li><li>"Você é um copywriter: reescreva este anúncio".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Seja específico no papel (nível de senioridade, área).</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Persona genérica não muda nada.</li></ul><h3>📌 Resumo final</h3><p>Persona é direção. Use sempre.</p><h3>✏️ Exercício de fixação</h3><p>Teste o mesmo prompt com 3 personas diferentes e compare.</p>', '', 1, 25, true, 'Aplicar a técnica de persona para refinar respostas da IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Mude a persona, mude a resposta. Pequeno truque, grande efeito.', 'Persona é direção. Use sempre.', 'Apresentar Personas e Papéis: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Teste o mesmo prompt com 3 personas diferentes e compare.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os86', 'aula-6-1', 'Persona: Papel da IA', 'Persona é dizer à IA quem ela deve ser antes de responder. Quando você define o papel, a resposta muda em vocabulário, foco e profundidade.', '/slides/m06/aula-6-1-01.png', 1),
  ('os87', 'aula-6-1', 'Como Montar a Persona', 'Uma boa persona combina cargo, senioridade, área e objetivo. Em vez de pedir só "revise", diga: atue como consultor sênior e revise buscando gargalos.', '/slides/m06/aula-6-1-02.png', 2),
  ('os88', 'aula-6-1', 'Mesmo Pedido, Olhares Diferentes', 'O mesmo texto pode ser revisado por um auditor, copywriter ou analista de RH. Cada persona muda o critério de análise e o tipo de melhoria sugerida.', '/slides/m06/aula-6-1-03.png', 3),
  ('os89', 'aula-6-1', 'Persona Fraca x Forte', 'Persona genérica como "você é especialista" ajuda pouco. Persona forte informa experiência, área, foco da análise e tipo de entrega esperada.', '/slides/m06/aula-6-1-04.png', 4),
  ('os90', 'aula-6-1', 'Prática com 3 Personas', 'Teste o mesmo prompt com três personas diferentes e compare tom, profundidade, foco e utilidade. Salve a persona que entregou o melhor resultado.', '/slides/m06/aula-6-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q18', 'aula-6-1', 'Quiz: Personas e Papéis')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p52', 'q18', 'O que persona faz?', '[{"id":"a","texto":"Trava a IA."},{"id":"b","texto":"Direciona o tom e foco."},{"id":"c","texto":"Acelera resposta."},{"id":"d","texto":"Aumenta limite."}]'::jsonb, 'b', 1),
  ('p53', 'q18', 'Persona ruim é...', '[{"id":"a","texto":"Específica."},{"id":"b","texto":"Genérica."},{"id":"c","texto":"Detalhada."},{"id":"d","texto":"Profissional."}]'::jsonb, 'b', 2),
  ('p54', 'q18', 'Persona deve incluir...', '[{"id":"a","texto":"Nome próprio."},{"id":"b","texto":"Cargo e senioridade."},{"id":"c","texto":"CPF."},{"id":"d","texto":"Endereço."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-6-2', 'm06', 'Cadeias de Prompts', 'Dividir tarefas complexas em etapas para a IA.', 'Dividir tarefas complexas em etapas para a IA.', '<h3>🎯 Objetivo da aula</h3><p>Construir fluxos de prompts em cadeia.</p><h3>📖 Explicação</h3><div><p>Tarefas complexas saem melhor em etapas: primeiro extrair, depois analisar, depois resumir. Cada passo é um prompt, alimentado pelo anterior. É a base da automação inteligente.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Passo 1: extraia tópicos de uma reunião.</li><li>Passo 2: priorize por urgência.</li><li>Passo 3: gere e-mail de follow-up.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Documente a cadeia. Reuse.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Pedir tudo de uma vez e ter resultado fraco.</li></ul><h3>📌 Resumo final</h3><p>Quebre o problema. A IA agradece.</p><h3>✏️ Exercício de fixação</h3><p>Pegue uma tarefa complexa e quebre em 3 prompts encadeados.</p>', '', 2, 30, true, 'Construir fluxos de prompts em cadeia.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'IA não é mágica. É processo. Quebrar em etapas é o segredo.', 'Quebre o problema. A IA agradece.', 'Apresentar Cadeias de Prompts: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Pegue uma tarefa complexa e quebre em 3 prompts encadeados.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os91', 'aula-6-2', 'Cadeia de Prompts', 'Cadeia de prompts é dividir uma tarefa complexa em etapas. Primeiro extrair, depois analisar, depois resumir e só então gerar a ação final.', '/slides/m06/aula-6-2-01.png', 1),
  ('os92', 'aula-6-2', 'Por Que Quebrar a Tarefa', 'Um prompt enorme costuma gerar resposta confusa. Em cadeia, cada etapa fica clara, revisável e mais fácil de corrigir antes de seguir adiante.', '/slides/m06/aula-6-2-02.png', 2),
  ('os93', 'aula-6-2', 'Exemplo com Reunião', 'Use a cadeia assim: cole a transcrição, extraia os tópicos, priorize por urgência e gere um e-mail de follow-up com responsáveis e prazos.', '/slides/m06/aula-6-2-03.png', 3),
  ('os94', 'aula-6-2', 'Documente a Cadeia', 'Para reutilizar o processo, registre cada passo com entrada, saída esperada e próximo prompt. Isso transforma improviso em método de trabalho.', '/slides/m06/aula-6-2-04.png', 4),
  ('os95', 'aula-6-2', 'Quando Usar Cadeia', 'Use um prompt único para tarefas simples. Use cadeia quando houver várias etapas, como relatórios, reuniões, análises de dados e apresentações.', '/slides/m06/aula-6-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q19', 'aula-6-2', 'Quiz: Cadeias de Prompts')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p55', 'q19', 'Cadeia de prompts é...', '[{"id":"a","texto":"1 prompt longo."},{"id":"b","texto":"Vários prompts encadeados."},{"id":"c","texto":"Um robô físico."},{"id":"d","texto":"Plugin."}]'::jsonb, 'b', 1),
  ('p56', 'q19', 'Vantagem da cadeia?', '[{"id":"a","texto":"Mais rápido sempre."},{"id":"b","texto":"Resultado mais profundo e auditável."},{"id":"c","texto":"Mais barato."},{"id":"d","texto":"Sem revisão."}]'::jsonb, 'b', 2),
  ('p57', 'q19', 'Quando NÃO usar cadeia?', '[{"id":"a","texto":"Tarefa simples e única."},{"id":"b","texto":"Análise complexa."},{"id":"c","texto":"Pipeline de dados."},{"id":"d","texto":"Geração estruturada."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-6-3', 'm06', 'Análise de Dados com IA', 'Colar tabela, pedir insights, gerar gráficos.', 'Colar tabela, pedir insights, gerar gráficos.', '<h3>🎯 Objetivo da aula</h3><p>Extrair conclusões de dados usando IA.</p><h3>📖 Explicação</h3><div><p>IA é boa em encontrar padrões em dados. Cole uma tabela, peça insights, peça gráfico em código (Mermaid, Python). Funciona melhor com dados estruturados e contexto claro do que você procura.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>"Encontre padrões nas vendas deste trimestre".</li><li>"Sugira 3 gráficos que melhor mostram esta evolução".</li></ul><h3>💡 Dicas importantes</h3><ul><li>Anonimize antes.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar em número que a IA "inventou".</li></ul><h3>📌 Resumo final</h3><p>IA + dados = insight rápido. Mas confira sempre.</p><h3>✏️ Exercício de fixação</h3><p>Cole uma tabela (anonimizada) e peça 3 insights.</p>', '', 3, 30, true, 'Extrair conclusões de dados usando IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Análise de dados com IA é onde mais economiza tempo. Vem ver.', 'IA + dados = insight rápido. Mas confira sempre.', 'Apresentar Análise de Dados com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Cole uma tabela (anonimizada) e peça 3 insights.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os96', 'aula-6-3', 'Dados Entram, Insights Saem', 'A IA ajuda a transformar tabela ou CSV em insights. O melhor resultado vem quando você envia dados organizados e explica o que quer descobrir.', '/slides/m06/aula-6-3-01.png', 1),
  ('os97', 'aula-6-3', 'Prepare Antes de Colar', 'Antes de enviar dados, anonimize informações sensíveis, selecione as colunas certas, explique o contexto e defina a pergunta de análise.', '/slides/m06/aula-6-3-02.png', 2),
  ('os98', 'aula-6-3', 'Peça Insights Específicos', 'Não peça apenas "analise". Peça padrões, anomalias, tendências, gráficos recomendados e ações sugeridas para transformar dados em decisão.', '/slides/m06/aula-6-3-03.png', 3),
  ('os99', 'aula-6-3', 'Valide os Números', 'A IA pode interpretar errado ou inventar números. Sempre confira totais, períodos, fórmulas e valores críticos na fonte original antes de usar.', '/slides/m06/aula-6-3-04.png', 4),
  ('os100', 'aula-6-3', 'Prompt Base de Análise', 'Use um modelo: analise estes dados e entregue resumo executivo, três tendências, anomalias, gráficos recomendados e ações sugeridas.', '/slides/m06/aula-6-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q20', 'aula-6-3', 'Quiz: Análise de Dados com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p58', 'q20', 'Antes de colar tabela na IA pública?', '[{"id":"a","texto":"Compactar."},{"id":"b","texto":"Anonimizar."},{"id":"c","texto":"Criptografar."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'b', 1),
  ('p59', 'q20', 'IA é boa em achar...', '[{"id":"a","texto":"Senhas."},{"id":"b","texto":"Padrões nos dados."},{"id":"c","texto":"Fotos."},{"id":"d","texto":"Endereços."}]'::jsonb, 'b', 2),
  ('p60', 'q20', 'Antes de citar um número da IA?', '[{"id":"a","texto":"Validar."},{"id":"b","texto":"Compartilhar."},{"id":"c","texto":"Imprimir."},{"id":"d","texto":"Confiar cego."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-6-4', 'm06', 'Criação de Conteúdo Avançado', 'Textos, apresentações e roteiros com qualidade profissional.', 'Textos, apresentações e roteiros com qualidade profissional.', '<h3>🎯 Objetivo da aula</h3><p>Produzir conteúdo profissional combinando prompts e revisão.</p><h3>📖 Explicação</h3><div><p>Para conteúdo de alto nível, combine: persona forte, exemplos do seu próprio estilo, revisão em ciclos. Use a IA como rascunho rápido — você como editor final.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Apresentação de 10 slides para diretoria.</li><li>Roteiro de vídeo institucional.</li><li>Artigo para LinkedIn no seu estilo.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Treine a IA com 2-3 exemplos do seu próprio estilo.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Aceitar tudo de primeira.</li></ul><h3>📌 Resumo final</h3><p>Combine persona + exemplos do seu estilo + revisão. Resultado: nível pro.</p><h3>✏️ Exercício de fixação</h3><p>Produza um post de LinkedIn no seu estilo, em 3 iterações.</p>', '', 4, 30, true, 'Produzir conteúdo profissional combinando prompts e revisão.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Conteúdo de qualidade não nasce pronto. É IA + você. Vamos refinar juntos.', 'Combine persona + exemplos do seu estilo + revisão. Resultado: nível pro.', 'Apresentar Criação de Conteúdo Avançado: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Produza um post de LinkedIn no seu estilo, em 3 iterações.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os101', 'aula-6-4', 'Conteúdo Avançado com IA', 'Para criar conteúdo profissional, combine persona forte, exemplos do seu estilo e revisão em ciclos. A IA acelera o rascunho, mas você dirige.', '/slides/m06/aula-6-4-01.png', 1),
  ('os102', 'aula-6-4', 'Ensine Seu Estilo', 'Cole dois ou três textos seus e peça para a IA observar tom, vocabulário, ritmo e formalidade. Depois solicite o novo conteúdo nesse padrão.', '/slides/m06/aula-6-4-02.png', 2),
  ('os103', 'aula-6-4', 'Formatos Profissionais', 'Com bons prompts, a IA pode ajudar em apresentações, roteiros, posts e relatórios. O segredo é informar público, objetivo, formato e critério de qualidade.', '/slides/m06/aula-6-4-03.png', 3),
  ('os104', 'aula-6-4', 'Revise em 3 Rodadas', 'Trabalhe em ciclos: gere o rascunho, ajuste o tom, corte excessos e refine a versão final. Cada rodada resolve um tipo de problema.', '/slides/m06/aula-6-4-04.png', 4),
  ('os105', 'aula-6-4', 'Você é o Editor Final', 'A IA produz opções, mas a decisão final é humana. Antes de publicar, confira clareza, dados corretos, tom adequado e objetivo cumprido.', '/slides/m06/aula-6-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q21', 'aula-6-4', 'Quiz: Criação de Conteúdo Avançado')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p61', 'q21', 'O que falta na IA em conteúdo de alto nível?', '[{"id":"a","texto":"Seu estilo pessoal."},{"id":"b","texto":"Velocidade."},{"id":"c","texto":"Vocabulário."},{"id":"d","texto":"Memória."}]'::jsonb, 'a', 1),
  ('p62', 'q21', 'Iteração média recomendada?', '[{"id":"a","texto":"1 vez."},{"id":"b","texto":"3 vezes."},{"id":"c","texto":"20 vezes."},{"id":"d","texto":"0 vezes."}]'::jsonb, 'b', 2),
  ('p63', 'q21', 'Quem decide o resultado final?', '[{"id":"a","texto":"A IA."},{"id":"b","texto":"O humano."},{"id":"c","texto":"A internet."},{"id":"d","texto":"O chefe."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m07', 'M07 - Documentação Corporativa', 'E-mails, relatórios, atas e comunicados com IA.', 7, 4, true, '/covers/m07-documentos-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-7-1', 'm07', 'E-mails Profissionais', 'Escreva e responda e-mails em segundos com tom certo.', 'Escreva e responda e-mails em segundos com tom certo.', '<h3>🎯 Objetivo da aula</h3><p>Usar IA para acelerar a produção de e-mails de qualidade.</p><h3>📖 Explicação</h3><div><p>E-mail consome horas. Com IA, você reduz para minutos. Cole bullets, peça draft, ajuste tom, envie. Templates por tipo (cobrança, agradecimento, reunião) aceleram ainda mais.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Resposta a reclamação de cliente.</li><li>Cobrança polida de fornecedor.</li><li>Convocação de reunião com pauta.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Especifique sempre tom e tamanho.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Esquecer de revisar nome do destinatário.</li></ul><h3>📌 Resumo final</h3><p>E-mail com IA: bullets → draft → ajuste → envia.</p><h3>✏️ Exercício de fixação</h3><p>Reescreva 3 e-mails seus desta semana usando IA.</p>', '', 1, 20, true, 'Usar IA para acelerar a produção de e-mails de qualidade.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Quantos e-mails você responde por dia? E se cada um tomasse 80% menos tempo?', 'E-mail com IA: bullets → draft → ajuste → envia.', 'Apresentar E-mails Profissionais: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Reescreva 3 e-mails seus desta semana usando IA.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os106', 'aula-7-1', 'E-mail com IA', 'Use IA para transformar bullets em uma resposta profissional. Informe contexto, destinatario, tom, objetivo e limite de tamanho. A IA cria o rascunho e voce revisa antes de enviar.', '/slides/m07/aula-7-1-01.png', 1),
  ('os107', 'aula-7-1', 'Triagem Inteligente', 'Classifique a caixa de entrada em urgente, importante, informativo e delegavel. A IA ajuda a resumir cada mensagem, sugerir prioridade e indicar a proxima acao.', '/slides/m07/aula-7-1-02.png', 2),
  ('os108', 'aula-7-1', 'Resposta por Tipo', 'Cada e-mail exige um tom: reclamacao pede empatia, follow-up pede leveza, fornecedor pede firmeza e comunicado urgente pede clareza. Defina o tipo antes do rascunho.', '/slides/m07/aula-7-1-03.png', 3),
  ('os109', 'aula-7-1', 'Outlook e Gmail', 'No Outlook ou Gmail, use IA para redigir e refinar mensagens. Depois organize a rotina com regras, filtros, labels e pastas para reduzir repeticao manual.', '/slides/m07/aula-7-1-04.png', 4),
  ('os110', 'aula-7-1', 'Checklist de Envio', 'Antes de clicar em enviar, confira nome, dados, valores, anexos, tom e chamada para acao. A IA acelera o texto, mas a aprovacao final continua humana.', '/slides/m07/aula-7-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q22', 'aula-7-1', 'Quiz: E-mails Profissionais')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p64', 'q22', 'O que sempre deve revisar?', '[{"id":"a","texto":"Cor da fonte."},{"id":"b","texto":"Nome do destinatário e dados."},{"id":"c","texto":"Tamanho do anexo."},{"id":"d","texto":"Fonte."}]'::jsonb, 'b', 1),
  ('p65', 'q22', 'Antes do draft, dê...', '[{"id":"a","texto":"Café."},{"id":"b","texto":"Bullets do conteúdo."},{"id":"c","texto":"Música."},{"id":"d","texto":"Imagem."}]'::jsonb, 'b', 2),
  ('p66', 'q22', 'Para que serve um template?', '[{"id":"a","texto":"Decorar."},{"id":"b","texto":"Acelerar com qualidade."},{"id":"c","texto":"Travar a IA."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-7-2', 'm07', 'Relatórios e Pareceres', 'Da matéria-prima ao relatório finalizado com IA.', 'Da matéria-prima ao relatório finalizado com IA.', '<h3>🎯 Objetivo da aula</h3><p>Produzir relatórios estruturados com auxílio de IA.</p><h3>📖 Explicação</h3><div><p>IA é ótima em estruturar relatórios: introdução, contexto, análise, recomendação, conclusão. Cole dados e pontos, peça estrutura, revise. Para parecer, use persona de especialista (jurídico, técnico).</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Relatório de vendas trimestral.</li><li>Parecer de viabilidade.</li><li>Análise de fornecedor.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use estrutura padrão da sua empresa.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Citar dados que a IA "inventou".</li></ul><h3>📌 Resumo final</h3><p>IA estrutura, você valida e assina.</p><h3>✏️ Exercício de fixação</h3><p>Produza um relatório de 1 página com IA hoje.</p>', '', 2, 30, true, 'Produzir relatórios estruturados com auxílio de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Relatórios não precisam ser sofrimento. Aprenda a delegar a estrutura.', 'IA estrutura, você valida e assina.', 'Apresentar Relatórios e Pareceres: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Produza um relatório de 1 página com IA hoje.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os111', 'aula-7-2', 'Documento Longo', 'Use IA para transformar documentos extensos em estrutura de trabalho. Peca partes principais, resumo executivo, riscos, obrigacoes e proximos passos.', '/slides/m07/aula-7-2-01.png', 1),
  ('os112', 'aula-7-2', 'Relatorio Executivo', 'Um bom relatorio com IA combina contexto, indicadores, analise, recomendacao e conclusao. Forneca dados reais e peca uma entrega objetiva para decisao.', '/slides/m07/aula-7-2-02.png', 2),
  ('os113', 'aula-7-2', 'Parecer com Persona', 'Para parecer tecnico, defina a persona: area, senioridade, criterio de avaliacao e formato esperado. A IA organiza argumentos, mas voce valida evidencias.', '/slides/m07/aula-7-2-03.png', 3),
  ('os114', 'aula-7-2', 'Word com IA', 'No Word, gere rascunho por secoes: objetivo, contexto, analise, recomendacao e fechamento. Aplique estilos, revise linguagem e finalize no padrao da empresa.', '/slides/m07/aula-7-2-04.png', 4),
  ('os115', 'aula-7-2', 'Valide os Dados', 'Nunca entregue relatorio sem conferir fonte, periodo, valores, premissas e conclusoes. IA melhora forma e fluxo, mas nao substitui verificacao dos numeros.', '/slides/m07/aula-7-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q23', 'aula-7-2', 'Quiz: Relatórios e Pareceres')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p67', 'q23', 'A estrutura sai com IA. O que NÃO sai?', '[{"id":"a","texto":"Dados verídicos da sua empresa."},{"id":"b","texto":"Fluxo."},{"id":"c","texto":"Redação."},{"id":"d","texto":"Tom."}]'::jsonb, 'a', 1),
  ('p68', 'q23', 'Persona ideal para parecer técnico?', '[{"id":"a","texto":"Especialista da área."},{"id":"b","texto":"Estagiário."},{"id":"c","texto":"Atendente."},{"id":"d","texto":"Vendedor."}]'::jsonb, 'a', 2),
  ('p69', 'q23', 'O que checar antes de entregar?', '[{"id":"a","texto":"Dados e fonte."},{"id":"b","texto":"Cor do título."},{"id":"c","texto":"Tamanho da fonte."},{"id":"d","texto":"Margem."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-7-3', 'm07', 'Atas de Reunião', 'De transcrição a ata profissional em minutos.', 'De transcrição a ata profissional em minutos.', '<h3>🎯 Objetivo da aula</h3><p>Gerar atas estruturadas a partir de transcrições.</p><h3>📖 Explicação</h3><div><p>Cole a transcrição (do Teams, Meet, Zoom), peça à IA: "estruture em decisões, pendências, responsáveis e prazos". Em segundos, ata pronta. Sempre revise nomes e datas.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Reunião semanal.</li><li>Comitê executivo.</li><li>Reunião com cliente.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Padronize a estrutura para revisar mais rápido.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Não revisar responsáveis e prazos.</li></ul><h3>📌 Resumo final</h3><p>Transcrição + prompt = ata em minutos.</p><h3>✏️ Exercício de fixação</h3><p>Pegue uma transcrição e gere ata. Compare com seu modelo manual.</p>', '', 3, 20, true, 'Gerar atas estruturadas a partir de transcrições.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Atas de reunião agora levam minutos. Quem souber, ganha tempo todo dia.', 'Transcrição + prompt = ata em minutos.', 'Apresentar Atas de Reunião: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Pegue uma transcrição e gere ata. Compare com seu modelo manual.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os116', 'aula-7-3', 'Ata em Minutos', 'Cole a transcricao ou anotacoes da reuniao e peca uma ata com participantes, decisoes, pendencias, responsaveis e prazos. O ganho vem da estrutura pronta.', '/slides/m07/aula-7-3-01.png', 1),
  ('os117', 'aula-7-3', 'Mapa da Reuniao', 'Separe conversa de compromisso. A IA pode identificar topicos, acordos, duvidas, acoes e riscos para transformar a reuniao em acompanhamento claro.', '/slides/m07/aula-7-3-02.png', 2),
  ('os118', 'aula-7-3', 'Tabela de Acoes', 'Toda ata profissional precisa deixar claro quem faz o que e ate quando. Peca uma tabela com responsavel, tarefa, prazo, status e observacoes.', '/slides/m07/aula-7-3-03.png', 3),
  ('os119', 'aula-7-3', 'Revisao da Ata', 'Antes de circular, revise nomes, datas, decisoes, prazos e anexos. Erros pequenos em ata criam cobrancas erradas e desalinhamento entre equipes.', '/slides/m07/aula-7-3-04.png', 4),
  ('os120', 'aula-7-3', 'Follow-up Automatico', 'Depois da ata aprovada, use IA para gerar uma mensagem de acompanhamento com resumo, pendencias, responsaveis, chamada para acao e prazo de retorno.', '/slides/m07/aula-7-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q24', 'aula-7-3', 'Quiz: Atas de Reunião')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p70', 'q24', 'O que pedir à IA para ata?', '[{"id":"a","texto":"Estrutura: decisões, pendências, responsáveis, prazos."},{"id":"b","texto":"Fofocar."},{"id":"c","texto":"Resumir trivialidades."},{"id":"d","texto":"Repetir tudo."}]'::jsonb, 'a', 1),
  ('p71', 'q24', 'Sempre revisar...', '[{"id":"a","texto":"Nomes e datas."},{"id":"b","texto":"Cor."},{"id":"c","texto":"Fonte."},{"id":"d","texto":"Margem."}]'::jsonb, 'a', 2),
  ('p72', 'q24', 'A IA precisa de qual insumo?', '[{"id":"a","texto":"Vídeo."},{"id":"b","texto":"Transcrição."},{"id":"c","texto":"Foto."},{"id":"d","texto":"Áudio bruto sem texto."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-7-4', 'm07', 'Comunicados Internos', 'Mensagens claras para toda empresa em qualquer tom.', 'Mensagens claras para toda empresa em qualquer tom.', '<h3>🎯 Objetivo da aula</h3><p>Produzir comunicados internos eficazes com IA.</p><h3>📖 Explicação</h3><div><p>Comunicados internos precisam clareza, tom adequado e ação clara. IA ajuda a balancear: nem frio, nem confuso. Especifique público, urgência e ação esperada.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Mudança de processo.</li><li>Aviso de manutenção.</li><li>Anúncio de evento.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comunicado curto vence comunicado longo.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Não deixar claro o que esperar do leitor.</li></ul><h3>📌 Resumo final</h3><p>Curto, claro, com ação. IA ajuda nas 3.</p><h3>✏️ Exercício de fixação</h3><p>Produza um comunicado de mudança de processo em 100 palavras.</p>', '', 4, 20, true, 'Produzir comunicados internos eficazes com IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Comunicado claro evita reunião. Aprenda a fazer rápido e bem.', 'Curto, claro, com ação. IA ajuda nas 3.', 'Apresentar Comunicados Internos: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Produza um comunicado de mudança de processo em 100 palavras.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os121', 'aula-7-4', 'Comunicado Claro', 'Comunicado interno bom responde: o que mudou, por que mudou, quem e afetado, o que fazer agora e qual prazo seguir. Clareza reduz retrabalho.', '/slides/m07/aula-7-4-01.png', 1),
  ('os122', 'aula-7-4', 'Publico e Tom', 'A mesma mensagem muda conforme o leitor. Informe se o publico e equipe, lideranca, cliente interno ou toda a empresa, e defina tom formal, proximo ou urgente.', '/slides/m07/aula-7-4-02.png', 2),
  ('os123', 'aula-7-4', 'Comunicado Curto', 'Limite o comunicado a 100 ou 150 palavras quando possivel. Use titulo claro, contexto rapido, acao esperada, prazo e canal para duvidas.', '/slides/m07/aula-7-4-03.png', 3),
  ('os124', 'aula-7-4', 'Evite Ruido', 'Evite jargao, ambiguidade, excesso de historico e frases sem acao. Um comunicado bom permite que a pessoa saiba exatamente o que fazer depois de ler.', '/slides/m07/aula-7-4-04.png', 4),
  ('os125', 'aula-7-4', 'Prompt Base', 'Use um modelo simples: escreva para este publico, com este objetivo, neste tom, em ate este tamanho, deixando clara a acao esperada e o prazo.', '/slides/m07/aula-7-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q25', 'aula-7-4', 'Quiz: Comunicados Internos')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p73', 'q25', 'O que sempre deve constar?', '[{"id":"a","texto":"O que fazer."},{"id":"b","texto":"O CEP."},{"id":"c","texto":"Histórico de 10 anos."},{"id":"d","texto":"Foto."}]'::jsonb, 'a', 1),
  ('p74', 'q25', 'Tamanho ideal?', '[{"id":"a","texto":"100–150 palavras."},{"id":"b","texto":"2000 palavras."},{"id":"c","texto":"1 palavra."},{"id":"d","texto":"10 mil palavras."}]'::jsonb, 'a', 2),
  ('p75', 'q25', 'O que falta especificar no prompt?', '[{"id":"a","texto":"Cor."},{"id":"b","texto":"Tom e ação."},{"id":"c","texto":"Tamanho de fonte."},{"id":"d","texto":"IP do servidor."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m08', 'M08 - IA para Excel', 'Fórmulas, tabelas, dashboards e análise de dados.', 8, 4, true, '/covers/m08-excel-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-8-1', 'm08', 'Fórmulas com IA', 'Peça fórmulas em português, receba em PROCV/SOMASE/etc.', 'Peça fórmulas em português, receba em PROCV/SOMASE/etc.', '<h3>🎯 Objetivo da aula</h3><p>Gerar fórmulas Excel a partir de descrição em português.</p><h3>📖 Explicação</h3><div><p>Em vez de decorar PROCV, ÍNDICE, CORRESP, peça à IA. Descreva o que quer ("buscar nome do cliente na coluna B da aba Clientes a partir do CPF da célula A2"). IA devolve a fórmula pronta para colar.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>PROCV substituído por descrição.</li><li>Fórmula matricial gerada em segundos.</li><li>Macro VBA básica.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Sempre teste em poucos dados primeiro.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar sem testar com casos extremos.</li></ul><h3>📌 Resumo final</h3><p>Fórmula que você não lembra, IA gera. Você só testa.</p><h3>✏️ Exercício de fixação</h3><p>Peça à IA uma fórmula SOMASE para sua planilha de despesas.</p>', '', 1, 25, true, 'Gerar fórmulas Excel a partir de descrição em português.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Esqueceu fórmula? Esqueça. A IA virou seu dicionário Excel ao vivo.', 'Fórmula que você não lembra, IA gera. Você só testa.', 'Apresentar Fórmulas com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Peça à IA uma fórmula SOMASE para sua planilha de despesas.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os126', 'aula-8-1', 'IA para Planilhas', 'Voce descreve em linguagem simples e a IA ajuda a criar a formula. O fluxo ideal e explicar objetivo, contexto da planilha, formula sugerida, colar no Excel e conferir o resultado.', '/slides/m08/aula-8-1-01.png', 1),
  ('os127', 'aula-8-1', 'Prompt de Formula', 'Um bom prompt informa objetivo, colunas, linha inicial, celula de destino e regra de calculo. Quanto mais clara a descricao da planilha, melhor a formula sugerida.', '/slides/m08/aula-8-1-02.png', 2),
  ('os128', 'aula-8-1', 'Formulas Mais Pedidas', 'A IA ajuda em demandas comuns: somar com condicao, buscar valor, classificar faixas e contar itens. Use a resposta como ponto de partida e teste na planilha.', '/slides/m08/aula-8-1-03.png', 3),
  ('os129', 'aula-8-1', 'Corrigir Erros', 'Quando a formula falhar, copie a mensagem de erro, explique onde ela foi colada e peca diagnostico. A IA pode sugerir ajuste de intervalo, separador ou sintaxe.', '/slides/m08/aula-8-1-04.png', 4),
  ('os130', 'aula-8-1', 'Conferir Resultado', 'Formula pronta ainda precisa validacao. Confira celula correta, intervalo correto, separador, resultado esperado e um teste manual simples antes de usar.', '/slides/m08/aula-8-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q26', 'aula-8-1', 'Quiz: Fórmulas com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p76', 'q26', 'O que descrever para a IA?', '[{"id":"a","texto":"O que a fórmula deve fazer, em português."},{"id":"b","texto":"O CEP."},{"id":"c","texto":"A senha."},{"id":"d","texto":"O Wi-Fi."}]'::jsonb, 'a', 1),
  ('p77', 'q26', 'O que fazer com a fórmula?', '[{"id":"a","texto":"Confiar cega."},{"id":"b","texto":"Testar em alguns casos."},{"id":"c","texto":"Imprimir."},{"id":"d","texto":"Ignorar."}]'::jsonb, 'b', 2),
  ('p78', 'q26', 'IA gera VBA básico?', '[{"id":"a","texto":"Sim."},{"id":"b","texto":"Não."},{"id":"c","texto":"Só com plugin."},{"id":"d","texto":"Só pagando."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-8-2', 'm08', 'Tabelas e Dinâmicas', 'Organize dados e gere tabelas dinâmicas guiado por IA.', 'Organize dados e gere tabelas dinâmicas guiado por IA.', '<h3>🎯 Objetivo da aula</h3><p>Usar IA para projetar tabelas dinâmicas eficazes.</p><h3>📖 Explicação</h3><div><p>IA ajuda a decidir o que vai em linhas, colunas, valores e filtros. Descreva sua planilha e o que quer ver — ela sugere a estrutura ideal e o passo a passo no Excel.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Vendas por região e mês.</li><li>Despesas por categoria.</li><li>Equipe por projeto.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use Tabela Estruturada (Ctrl+T) antes da dinâmica.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Não nomear cabeçalhos claros.</li></ul><h3>📌 Resumo final</h3><p>IA sugere estrutura. Você executa no Excel.</p><h3>✏️ Exercício de fixação</h3><p>Crie uma tabela dinâmica guiada por IA com sua planilha.</p>', '', 2, 30, true, 'Usar IA para projetar tabelas dinâmicas eficazes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Tabela dinâmica assusta? Hoje a IA fica do seu lado.', 'IA sugere estrutura. Você executa no Excel.', 'Apresentar Tabelas e Dinâmicas: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie uma tabela dinâmica guiada por IA com sua planilha.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os131', 'aula-8-2', 'Tabela Bem Preparada', 'Antes da analise, organize a base: sem linhas vazias, uma coluna por campo, cabecalhos claros, dados consistentes e tabela estruturada com Ctrl+T.', '/slides/m08/aula-8-2-01.png', 1),
  ('os132', 'aula-8-2', 'Dinamica Guiada por IA', 'Descreva o que quer descobrir e peca sugestao de linhas, colunas, valores e filtros. A IA orienta a estrutura; voce executa no Excel e valida.', '/slides/m08/aula-8-2-02.png', 2),
  ('os133', 'aula-8-2', 'Pergunta de Negocio', 'Toda tabela dinamica deve responder uma decisao. Comece pela pergunta, escolha os campos, monte a tabela, leia o insight e defina a acao.', '/slides/m08/aula-8-2-03.png', 3),
  ('os134', 'aula-8-2', 'Segmentacao e Filtros', 'Filtros e segmentacoes permitem analisar recortes de mes, regiao, categoria e responsavel sem refazer tudo. Eles transformam uma base em varias leituras.', '/slides/m08/aula-8-2-04.png', 4),
  ('os135', 'aula-8-2', 'Erros em Dinamicas', 'Dados ruins geram analise ruim. Corrija cabecalho vazio, data como texto, categoria duplicada, valor em branco e total misturado antes de confiar no resultado.', '/slides/m08/aula-8-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q27', 'aula-8-2', 'Quiz: Tabelas e Dinâmicas')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p79', 'q27', 'Atalho para tabela estruturada?', '[{"id":"a","texto":"Ctrl+T."},{"id":"b","texto":"Ctrl+C."},{"id":"c","texto":"Ctrl+V."},{"id":"d","texto":"Ctrl+Z."}]'::jsonb, 'a', 1),
  ('p80', 'q27', 'O que a IA sugere?', '[{"id":"a","texto":"A estrutura linhas/colunas/valores."},{"id":"b","texto":"O preço."},{"id":"c","texto":"A imagem."},{"id":"d","texto":"O backup."}]'::jsonb, 'a', 2),
  ('p81', 'q27', 'Cabeçalho ideal?', '[{"id":"a","texto":"Curto e claro."},{"id":"b","texto":"Longo."},{"id":"c","texto":"Com emoji."},{"id":"d","texto":"Em caixa alta colorida."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-8-3', 'm08', 'Dashboards', 'Dashboard executivo no Excel com auxílio de IA.', 'Dashboard executivo no Excel com auxílio de IA.', '<h3>🎯 Objetivo da aula</h3><p>Estruturar e construir um dashboard com IA.</p><h3>📖 Explicação</h3><div><p>Dashboard começa com perguntas-chave do gestor. Peça à IA para sugerir KPIs, gráficos e layout. Depois execute com tabelas dinâmicas e segmentações de dados.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Dashboard de vendas.</li><li>Dashboard financeiro.</li><li>Dashboard de RH.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Máx 5 KPIs principais. Mais é confusão.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Dashboard sem pergunta clara responde nada.</li></ul><h3>📌 Resumo final</h3><p>Pergunta → KPI → gráfico. Nessa ordem.</p><h3>✏️ Exercício de fixação</h3><p>Construa um mini dashboard com 3 KPIs.</p>', '', 3, 30, true, 'Estruturar e construir um dashboard com IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Dashboard não é arte — é decisão. A IA te ajuda a focar.', 'Pergunta → KPI → gráfico. Nessa ordem.', 'Apresentar Dashboards: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Construa um mini dashboard com 3 KPIs.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os136', 'aula-8-3', 'Dashboard com IA', 'Dashboard bom segue uma ordem simples: pergunta, KPI, base, grafico e decisao. A IA ajuda a desenhar a estrutura, mas a pergunta vem do negocio.', '/slides/m08/aula-8-3-01.png', 1),
  ('os137', 'aula-8-3', 'KPIs Principais', 'Use no maximo cinco indicadores por tela. Poucos KPIs bem escolhidos facilitam leitura, reduzem confusao e ajudam a lideranca a decidir rapido.', '/slides/m08/aula-8-3-02.png', 2),
  ('os138', 'aula-8-3', 'Grafico Certo', 'Cada pergunta pede uma visualizacao: linha para tendencia, barra para comparacao, pizza para participacao e cartao para indicador. Valide se o grafico responde.', '/slides/m08/aula-8-3-03.png', 3),
  ('os139', 'aula-8-3', 'Layout Executivo', 'Organize a leitura: KPIs no topo, grafico principal ao centro, filtros laterais e alertas no rodape. A decisao precisa aparecer sem procurar informacao.', '/slides/m08/aula-8-3-04.png', 4),
  ('os140', 'aula-8-3', 'Revisao do Dashboard', 'Bonito nao basta. Confira pergunta clara, dados atualizados, filtros funcionando, graficos coerentes e acao recomendada antes de apresentar.', '/slides/m08/aula-8-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q28', 'aula-8-3', 'Quiz: Dashboards')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p82', 'q28', 'Dashboard começa com...', '[{"id":"a","texto":"Pergunta."},{"id":"b","texto":"Cor."},{"id":"c","texto":"Fonte."},{"id":"d","texto":"Logo."}]'::jsonb, 'a', 1),
  ('p83', 'q28', 'Quantos KPIs principais?', '[{"id":"a","texto":"Até 5."},{"id":"b","texto":"50."},{"id":"c","texto":"100."},{"id":"d","texto":"0."}]'::jsonb, 'a', 2),
  ('p84', 'q28', 'Dashboard sem pergunta é...', '[{"id":"a","texto":"Útil."},{"id":"b","texto":"Confuso."},{"id":"c","texto":"Premiado."},{"id":"d","texto":"Padrão ouro."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-8-4', 'm08', 'Análise de Dados no Excel', 'Insights, anomalias e tendências guiados por IA.', 'Insights, anomalias e tendências guiados por IA.', '<h3>🎯 Objetivo da aula</h3><p>Extrair insights de planilhas com auxílio de IA.</p><h3>📖 Explicação</h3><div><p>Cole uma amostra anonimizada na IA e peça: padrões, anomalias, tendências, recomendações. Use as conclusões como hipóteses — valide no Excel com a base completa.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Análise de churn.</li><li>Análise de margem.</li><li>Análise de produtividade.</li></ul><h3>💡 Dicas importantes</h3><ul><li>IA dá hipótese; Excel dá prova.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar 100% na hipótese sem validar.</li></ul><h3>📌 Resumo final</h3><p>IA = hipótese. Excel = prova. Combinados, decisão sólida.</p><h3>✏️ Exercício de fixação</h3><p>Cole uma amostra, peça 3 hipóteses, valide 1 no Excel.</p>', '', 4, 30, true, 'Extrair insights de planilhas com auxílio de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Análise de dados é arte de fazer perguntas. A IA é seu parceiro de hipóteses.', 'IA = hipótese. Excel = prova. Combinados, decisão sólida.', 'Apresentar Análise de Dados no Excel: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Cole uma amostra, peça 3 hipóteses, valide 1 no Excel.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os141', 'aula-8-4', 'Insights com IA', 'Dados brutos viram hipoteses quando voce pede padroes, tendencias, anomalias e recomendacoes. A IA encontra pistas; o Excel confirma a prova.', '/slides/m08/aula-8-4-01.png', 1),
  ('os142', 'aula-8-4', 'Amostra Anonimizada', 'Antes de usar IA, remova nomes, oculte identificadores, mantenha contexto e envie apenas uma amostra segura. Protecao de dados vem antes da analise.', '/slides/m08/aula-8-4-02.png', 2),
  ('os143', 'aula-8-4', 'Prompt de Analise', 'Um bom prompt de analise informa contexto, objetivo, colunas, periodo e entrega esperada. Assim a IA sabe o que observar e como responder.', '/slides/m08/aula-8-4-03.png', 3),
  ('os144', 'aula-8-4', 'Validar no Excel', 'IA sugere e Excel comprova. Confirme conclusoes com formula, filtro, grafico e base completa antes de transformar uma hipotese em decisao.', '/slides/m08/aula-8-4-04.png', 4),
  ('os145', 'aula-8-4', 'Plano de Acao', 'Insight bom termina em decisao. Conecte insight, evidencia, prioridade, responsavel e proximo passo para transformar analise em resultado acompanhavel.', '/slides/m08/aula-8-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q29', 'aula-8-4', 'Quiz: Análise de Dados no Excel')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p85', 'q29', 'IA fornece...', '[{"id":"a","texto":"Hipótese."},{"id":"b","texto":"Prova."},{"id":"c","texto":"Backup."},{"id":"d","texto":"CEP."}]'::jsonb, 'a', 1),
  ('p86', 'q29', 'O que valida a hipótese?', '[{"id":"a","texto":"Excel sobre base completa."},{"id":"b","texto":"Foto."},{"id":"c","texto":"Cor."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'a', 2),
  ('p87', 'q29', 'Antes de enviar amostra?', '[{"id":"a","texto":"Anonimizar."},{"id":"b","texto":"Imprimir."},{"id":"c","texto":"Gravar áudio."},{"id":"d","texto":"Tirar print."}]'::jsonb, 'a', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m09', 'M09 - Automação', 'Zapier, Make e Power Automate com IA.', 9, 5, true, '/covers/m09-automacao-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-9-1', 'm09', 'Zapier com IA', 'Conecte apps e adicione IA no meio do fluxo.', 'Conecte apps e adicione IA no meio do fluxo.', '<h3>🎯 Objetivo da aula</h3><p>Construir um fluxo no Zapier com etapa de IA.</p><h3>📖 Explicação</h3><div><p>Zapier conecta apps (Gmail, Sheets, Slack...) e dispara automações. Agora ele tem etapas de IA: classificar, resumir, gerar resposta. Você cria fluxos em minutos sem código.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Novo e-mail → IA classifica → grava em planilha.</li><li>Formulário → IA resume → notifica Slack.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comece com 1 zap simples e expanda.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Criar zaps complexos demais antes de testar.</li></ul><h3>📌 Resumo final</h3><p>Zapier + IA = automação inteligente sem programar.</p><h3>✏️ Exercício de fixação</h3><p>Crie um zap simples: novo e-mail → IA resume → Slack.</p>', '', 1, 30, true, 'Construir um fluxo no Zapier com etapa de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Zapier ficou ainda mais poderoso com IA dentro. Vem ver na prática.', 'Zapier + IA = automação inteligente sem programar.', 'Apresentar Zapier com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie um zap simples: novo e-mail → IA resume → Slack.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os146', 'aula-9-1', 'Automacao com IA', 'Quando uma tarefa se repete, tem regra clara e consome tempo, ela pode virar automacao. O fluxo ideal conecta entrada, IA, acao e registro com revisao humana nos pontos criticos.', '/slides/m09/aula-9-1-01.png', 1),
  ('os147', 'aula-9-1', 'Zapier com IA', 'Zapier conecta ferramentas sem programar e permite colocar IA no meio do processo. Um e-mail pode ser classificado, resumido e registrado automaticamente.', '/slides/m09/aula-9-1-02.png', 2),
  ('os148', 'aula-9-1', 'Gatilho e Acao', 'Toda automacao comeca com um gatilho claro e uma acao definida. Se algo acontece, o fluxo executa o proximo passo de forma padronizada.', '/slides/m09/aula-9-1-03.png', 3),
  ('os149', 'aula-9-1', 'IA no Meio do Fluxo', 'A IA entra no fluxo para classificar, resumir ou decidir a rota. Depois, a automacao executa a acao correta: urgente, acompanhar ou arquivar.', '/slides/m09/aula-9-1-04.png', 4),
  ('os150', 'aula-9-1', 'Comece Simples', 'Automacao boa nasce pequena. Crie um zap por vez, teste com dados reais controlados, corrija falhas e so entao expanda para processos maiores.', '/slides/m09/aula-9-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q30', 'aula-9-1', 'Quiz: Zapier com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p88', 'q30', 'Zapier exige programar?', '[{"id":"a","texto":"Sim."},{"id":"b","texto":"Não."},{"id":"c","texto":"Só em JavaScript."},{"id":"d","texto":"Só com plugin."}]'::jsonb, 'b', 1),
  ('p89', 'q30', 'IA no Zapier serve para...', '[{"id":"a","texto":"Decorar."},{"id":"b","texto":"Classificar, resumir, decidir."},{"id":"c","texto":"Logar."},{"id":"d","texto":"Imprimir."}]'::jsonb, 'b', 2),
  ('p90', 'q30', 'Boa prática inicial?', '[{"id":"a","texto":"Começar simples."},{"id":"b","texto":"Começar complexo."},{"id":"c","texto":"Pular testes."},{"id":"d","texto":"Ignorar logs."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-9-2', 'm09', 'Make com IA', 'Visual, poderoso, com etapas avançadas.', 'Visual, poderoso, com etapas avançadas.', '<h3>🎯 Objetivo da aula</h3><p>Comparar Make com Zapier e construir um fluxo.</p><h3>📖 Explicação</h3><div><p>Make (ex-Integromat) é uma alternativa visual ao Zapier, com mais controle de fluxo e bom suporte a IA. Ideal quando o fluxo tem ramificações, iterações ou tratamento de erro.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Pipeline de processamento de dados.</li><li>Workflow de aprovação.</li><li>Sincronização entre sistemas.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Aprenda o conceito de "bundles" — é o que muda tudo.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Tentar fazer no Make o que é mais simples no Zapier.</li></ul><h3>📌 Resumo final</h3><p>Make = controle visual avançado. Use quando Zapier ficar simples demais.</p><h3>✏️ Exercício de fixação</h3><p>Replique um zap seu no Make com 1 etapa extra.</p>', '', 2, 30, true, 'Comparar Make com Zapier e construir um fluxo.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Make é o Zapier crescido. Hoje você conhece a diferença.', 'Make = controle visual avançado. Use quando Zapier ficar simples demais.', 'Apresentar Make com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Replique um zap seu no Make com 1 etapa extra.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os151', 'aula-9-2', 'Make com IA', 'Make e indicado quando o fluxo precisa de mais controle visual, ramificacoes e tratamento de dados. Ele ajuda a enxergar cada etapa como parte de um mapa.', '/slides/m09/aula-9-2-01.png', 1),
  ('os152', 'aula-9-2', 'Cenario Visual', 'No Make, cada modulo faz uma parte do trabalho: receber, transformar, analisar com IA, decidir rota e enviar resultado. O processo fica visivel e auditavel.', '/slides/m09/aula-9-2-02.png', 2),
  ('os153', 'aula-9-2', 'Bundles e Dados', 'Cada etapa recebe um pacote de dados, transforma e envia para a proxima etapa. A IA pode enriquecer esse pacote com resumo, prioridade ou classificacao.', '/slides/m09/aula-9-2-03.png', 3),
  ('os154', 'aula-9-2', 'Rotas e Condicoes', 'Make permite caminhos diferentes conforme regra ou classificacao. Se for urgente, segue uma rota; se for informativo, pode registrar ou arquivar.', '/slides/m09/aula-9-2-04.png', 4),
  ('os155', 'aula-9-2', 'Quando Usar Make', 'Use Make quando precisar visualizar, ramificar, tratar erro e transformar dados com mais detalhe. Para fluxos simples, uma ferramenta mais direta pode bastar.', '/slides/m09/aula-9-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q31', 'aula-9-2', 'Quiz: Make com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p91', 'q31', 'Make é alternativa a...', '[{"id":"a","texto":"Excel."},{"id":"b","texto":"Zapier."},{"id":"c","texto":"Google."},{"id":"d","texto":"Word."}]'::jsonb, 'b', 1),
  ('p92', 'q31', 'Quando preferir Make?', '[{"id":"a","texto":"Em fluxos com ramificação."},{"id":"b","texto":"Em zaps de 1 passo."},{"id":"c","texto":"Nunca."},{"id":"d","texto":"Sempre."}]'::jsonb, 'a', 2),
  ('p93', 'q31', 'O que é "bundle"?', '[{"id":"a","texto":"Cor."},{"id":"b","texto":"Conceito de pacote de dados no Make."},{"id":"c","texto":"Plugin."},{"id":"d","texto":"Logo."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-9-3', 'm09', 'Power Automate com IA', 'Automação Microsoft + AI Builder.', 'Automação Microsoft + AI Builder.', '<h3>🎯 Objetivo da aula</h3><p>Construir fluxos no Power Automate com IA.</p><h3>📖 Explicação</h3><div><p>Power Automate é a ferramenta de automação da Microsoft, integrada ao 365. Tem o AI Builder para extrair texto de documentos, classificar, prever. Ideal para empresas já no ecossistema Microsoft.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Aprovação de pedidos.</li><li>Extração de dados de notas fiscais.</li><li>Sincronização SharePoint.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use templates prontos do Power Automate.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Reinventar o que já existe pronto.</li></ul><h3>📌 Resumo final</h3><p>Power Automate = automação corporativa nativa Microsoft.</p><h3>✏️ Exercício de fixação</h3><p>Crie um fluxo simples: notificação no Teams a cada novo item em SharePoint.</p>', '', 3, 30, true, 'Construir fluxos no Power Automate com IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Se sua empresa é Microsoft, Power Automate é onde a automação mora.', 'Power Automate = automação corporativa nativa Microsoft.', 'Apresentar Power Automate com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie um fluxo simples: notificação no Teams a cada novo item em SharePoint.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os156', 'aula-9-3', 'Power Automate com IA', 'Power Automate combina automacao corporativa com etapas de IA. Ele e forte em ambientes com documentos, aprovacoes, equipes e registros internos.', '/slides/m09/aula-9-3-01.png', 1),
  ('os157', 'aula-9-3', 'Aprovacoes', 'Automacoes corporativas padronizam aprovacoes: solicitar, avaliar, aprovar, registrar e notificar. Cada pedido precisa de pessoa certa, prazo claro e status visivel.', '/slides/m09/aula-9-3-02.png', 2),
  ('os158', 'aula-9-3', 'Extracao de Documentos', 'A IA pode ler documentos, separar campos como cliente, data, valor, categoria e status, e alimentar tabelas ou sistemas sem digitacao manual repetitiva.', '/slides/m09/aula-9-3-03.png', 3),
  ('os159', 'aula-9-3', 'Templates Prontos', 'Nao reinvente o que ja existe. Comece por templates prontos, adapte campos, teste o fluxo e publique apenas depois de validar no processo real.', '/slides/m09/aula-9-3-04.png', 4),
  ('os160', 'aula-9-3', 'Governanca da Automacao', 'Automacao com IA precisa de dono do fluxo, permissoes, cuidado com dados sensiveis, logs e plano de erro. Sem governanca, o ganho vira risco.', '/slides/m09/aula-9-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q32', 'aula-9-3', 'Quiz: Power Automate com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p94', 'q32', 'Power Automate é de qual empresa?', '[{"id":"a","texto":"Google."},{"id":"b","texto":"Microsoft."},{"id":"c","texto":"Adobe."},{"id":"d","texto":"Apple."}]'::jsonb, 'b', 1),
  ('p95', 'q32', 'AI Builder serve para...', '[{"id":"a","texto":"Editar foto."},{"id":"b","texto":"OCR, classificação e previsão."},{"id":"c","texto":"Imprimir."},{"id":"d","texto":"Jogar."}]'::jsonb, 'b', 2),
  ('p96', 'q32', 'Boa prática?', '[{"id":"a","texto":"Usar templates."},{"id":"b","texto":"Sempre do zero."},{"id":"c","texto":"Sem teste."},{"id":"d","texto":"Sem documentação."}]'::jsonb, 'a', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m10', 'M10 - Processos Administrativos', 'POP, fluxogramas e checklists com IA.', 10, 4, true, '/covers/m10-processos-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-10-1', 'm10', 'POPs com IA', 'Procedimentos Operacionais Padrão gerados em minutos.', 'Procedimentos Operacionais Padrão gerados em minutos.', '<h3>🎯 Objetivo da aula</h3><p>Documentar processos como POPs com auxílio de IA.</p><h3>📖 Explicação</h3><div><p>POP é a documentação de um processo passo a passo. Com IA: descreva como você faz, peça estrutura em POP, revise. O que tomaria 2 horas vira 15 minutos.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>POP de fechamento mensal.</li><li>POP de atendimento.</li><li>POP de onboarding.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Inclua o "por quê" de cada passo.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>POP genérico vira papel de gaveta.</li></ul><h3>📌 Resumo final</h3><p>POP bom é específico e usado. IA acelera, você refina.</p><h3>✏️ Exercício de fixação</h3><p>Documente seu processo mais repetitivo como POP.</p>', '', 1, 25, true, 'Documentar processos como POPs com auxílio de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'POP não precisa ser chato. Com IA, vira ágil e útil.', 'POP bom é específico e usado. IA acelera, você refina.', 'Apresentar POPs com IA: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Documente seu processo mais repetitivo como POP.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os161', 'aula-10-1', 'POP com IA', 'A IA acelera a criacao de procedimentos operacionais padrao. Voce descreve o processo real, recebe uma estrutura inicial e valida cada etapa antes de publicar.', '/slides/m10/aula-10-1-01.png', 1),
  ('os162', 'aula-10-1', 'Estrutura do POP', 'Um POP profissional organiza objetivo, abrangencia, responsavel, passo a passo e evidencias. Essa estrutura permite que qualquer pessoa execute o processo do mesmo jeito.', '/slides/m10/aula-10-1-02.png', 2),
  ('os163', 'aula-10-1', 'Do Jeito Que Voce Faz', 'O melhor POP nasce da pratica real da equipe. Primeiro descreva como o trabalho acontece hoje, depois use IA para organizar, padronizar e melhorar a versao final.', '/slides/m10/aula-10-1-03.png', 3),
  ('os164', 'aula-10-1', 'Pontos de Atencao', 'POP util mostra onde o processo costuma falhar. Inclua erros comuns, excecoes, riscos, conferencias e evidencias para reduzir retrabalho e duvidas.', '/slides/m10/aula-10-1-04.png', 4),
  ('os165', 'aula-10-1', 'POP Vivo', 'Um POP bom nao fica parado. Ele deve ser usado, revisado, ajustado, aprovado e atualizado conforme a equipe aprende com a rotina.', '/slides/m10/aula-10-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q33', 'aula-10-1', 'Quiz: POPs com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p97', 'q33', 'O que POP significa?', '[{"id":"a","texto":"Procedimento Operacional Padrão."},{"id":"b","texto":"Plano Online de Produção."},{"id":"c","texto":"Política Operacional Privada."},{"id":"d","texto":"Padrão Oficial Profissional."}]'::jsonb, 'a', 1),
  ('p98', 'q33', 'POP bom é...', '[{"id":"a","texto":"Genérico."},{"id":"b","texto":"Específico e usado."},{"id":"c","texto":"Decorativo."},{"id":"d","texto":"Confidencial sempre."}]'::jsonb, 'b', 2),
  ('p99', 'q33', 'Por que IA acelera POP?', '[{"id":"a","texto":"Estrutura passo a passo."},{"id":"b","texto":"Imprime."},{"id":"c","texto":"Pinta."},{"id":"d","texto":"Edita vídeo."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-10-2', 'm10', 'Fluxogramas', 'Diagrame processos com IA gerando código Mermaid.', 'Diagrame processos com IA gerando código Mermaid.', '<h3>🎯 Objetivo da aula</h3><p>Gerar fluxogramas de processo a partir de texto.</p><h3>📖 Explicação</h3><div><p>Descreva um processo em texto e peça à IA para gerar código Mermaid (ou draw.io). Cole no editor compatível e tenha o fluxograma profissional em segundos.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Fluxograma de aprovação.</li><li>Fluxograma de atendimento.</li><li>Fluxograma de compras.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use Mermaid: leve, free, integra com vários apps.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Fluxograma sem decisão clara.</li></ul><h3>📌 Resumo final</h3><p>Texto → IA → código Mermaid → fluxograma.</p><h3>✏️ Exercício de fixação</h3><p>Crie um fluxograma do seu processo de aprovação.</p>', '', 2, 25, true, 'Gerar fluxogramas de processo a partir de texto.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Diagrama profissional em minutos? A IA + Mermaid mostra como.', 'Texto → IA → código Mermaid → fluxograma.', 'Apresentar Fluxogramas: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie um fluxograma do seu processo de aprovação.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os166', 'aula-10-2', 'Fluxograma com IA', 'A IA transforma uma descricao textual de processo em um primeiro diagrama. Depois a equipe revisa o fluxo para confirmar se ele representa a pratica real.', '/slides/m10/aula-10-2-01.png', 1),
  ('os167', 'aula-10-2', 'Mermaid', 'Mermaid permite escrever diagramas como texto. A IA pode gerar um codigo simples com inicio, processo, decisao e fim para colar em ferramentas compativeis.', '/slides/m10/aula-10-2-02.png', 2),
  ('os168', 'aula-10-2', 'Decisoes Claras', 'Fluxograma bom mostra onde existe decisao e qual caminho seguir em cada resposta. Se a decisao for ambigua, o processo fica dificil de executar.', '/slides/m10/aula-10-2-03.png', 3),
  ('os169', 'aula-10-2', 'Revisar o Fluxo', 'O diagrama precisa bater com a pratica. Confira inicio claro, responsaveis, decisoes, excecoes e fim definido antes de compartilhar.', '/slides/m10/aula-10-2-04.png', 4),
  ('os170', 'aula-10-2', 'Do Fluxograma ao POP', 'Visualize primeiro e documente depois. O fluxograma ajuda a enxergar etapas, responsaveis e evidencias antes de transformar tudo em procedimento escrito.', '/slides/m10/aula-10-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q34', 'aula-10-2', 'Quiz: Fluxogramas')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p100', 'q34', 'Mermaid é...', '[{"id":"a","texto":"Editor de vídeo."},{"id":"b","texto":"Linguagem de diagrama em texto."},{"id":"c","texto":"IA."},{"id":"d","texto":"Planilha."}]'::jsonb, 'b', 1),
  ('p101', 'q34', 'Onde testar?', '[{"id":"a","texto":"mermaid.live."},{"id":"b","texto":"Photoshop."},{"id":"c","texto":"PowerPoint."},{"id":"d","texto":"Outlook."}]'::jsonb, 'a', 2),
  ('p102', 'q34', 'Fluxograma bom tem...', '[{"id":"a","texto":"Decisões claras."},{"id":"b","texto":"Apenas caixas."},{"id":"c","texto":"Sem direção."},{"id":"d","texto":"Só cor."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-10-3', 'm10', 'Checklists Inteligentes', 'Listas de verificação geradas e atualizadas com IA.', 'Listas de verificação geradas e atualizadas com IA.', '<h3>🎯 Objetivo da aula</h3><p>Criar checklists eficazes para garantir consistência.</p><h3>📖 Explicação</h3><div><p>Checklist é o "antídoto contra esquecimento". IA gera checklists completos para qualquer processo, e você refina com a realidade da sua operação.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Checklist de fim de mês.</li><li>Checklist de evento.</li><li>Checklist de onboarding.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Máx 10 itens por checklist — depois divida.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Checklist gigante que ninguém usa.</li></ul><h3>📌 Resumo final</h3><p>Checklist bom: curto, claro, usado todo dia.</p><h3>✏️ Exercício de fixação</h3><p>Crie checklist para sua tarefa mais crítica.</p>', '', 3, 20, true, 'Criar checklists eficazes para garantir consistência.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Pequenas listas, grandes resultados. Bem-vindo aos checklists inteligentes.', 'Checklist bom: curto, claro, usado todo dia.', 'Apresentar Checklists Inteligentes: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Crie checklist para sua tarefa mais crítica.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os171', 'aula-10-3', 'Checklist Inteligente', 'Checklist inteligente transforma conhecimento do processo em verificacao simples e repetivel. Ele ajuda a equipe a lembrar o que precisa ser conferido.', '/slides/m10/aula-10-3-01.png', 1),
  ('os172', 'aula-10-3', 'Checklist Curto', 'Checklist grande demais deixa de ser usado. Mantenha no maximo dez itens por lista e divida por etapa quando a rotina for mais longa.', '/slides/m10/aula-10-3-02.png', 2),
  ('os173', 'aula-10-3', 'Antes, Durante e Depois', 'Organizar o checklist por momento ajuda a equipe a verificar o que importa na hora certa: antes de comecar, durante a execucao e depois da entrega.', '/slides/m10/aula-10-3-03.png', 3),
  ('os174', 'aula-10-3', 'Responsavel e Evidencia', 'Checklist profissional mostra item, responsavel, prazo, evidencia e status. Assim ele deixa de ser so uma caixa marcada e vira registro auditavel.', '/slides/m10/aula-10-3-04.png', 4),
  ('os175', 'aula-10-3', 'Melhoria Continua', 'Checklist bom evolui com a pratica. Quando um erro real aparece, transforme o aprendizado em novo item, treine a equipe e revise de novo.', '/slides/m10/aula-10-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q35', 'aula-10-3', 'Quiz: Checklists Inteligentes')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p103', 'q35', 'Tamanho ideal?', '[{"id":"a","texto":"Até 10."},{"id":"b","texto":"100."},{"id":"c","texto":"1."},{"id":"d","texto":"50."}]'::jsonb, 'a', 1),
  ('p104', 'q35', 'Checklist gigante é...', '[{"id":"a","texto":"Ótimo."},{"id":"b","texto":"Ignorado."},{"id":"c","texto":"Premiado."},{"id":"d","texto":"Padrão."}]'::jsonb, 'b', 2),
  ('p105', 'q35', 'O que define checklist bom?', '[{"id":"a","texto":"Decoração."},{"id":"b","texto":"Curto, claro, usado."},{"id":"c","texto":"Cor."},{"id":"d","texto":"Imagem."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m11', 'M11 - Casos de Uso por Área', 'RH, Financeiro, Compras, Operações e Atendimento.', 11, 6, true, '/covers/m11-casos-uso-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-11-1', 'm11', 'IA no RH', 'Triagem, JDs, feedbacks e onboarding.', 'Triagem, JDs, feedbacks e onboarding.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar IA em processos de RH.</p><h3>📖 Explicação</h3><div><p>No RH a IA acelera triagem (resumir currículos), redação (job descriptions, anúncios), feedback (templates de avaliação) e onboarding (planos personalizados). Atenção redobrada com dado pessoal.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Resumo de currículo.</li><li>JD para vaga técnica.</li><li>Avaliação de desempenho.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Anonimize dados de candidato.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Discriminação por viés do modelo.</li></ul><h3>📌 Resumo final</h3><p>IA no RH: ganho real, com cuidado redobrado de dado e viés.</p><h3>✏️ Exercício de fixação</h3><p>Gere uma JD para uma vaga atual do seu time.</p>', '', 1, 25, true, 'Aplicar IA em processos de RH.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'RH é onde IA mais economiza tempo — e mais exige responsabilidade.', 'IA no RH: ganho real, com cuidado redobrado de dado e viés.', 'Apresentar IA no RH: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Gere uma JD para uma vaga atual do seu time.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os176', 'aula-11-1', 'IA no RH', 'No RH, a IA acelera triagem, descricao de vagas, feedbacks e onboarding. O ganho de tempo e real, mas dados pessoais, vies e decisao final exigem cuidado humano.', '/slides/m11/aula-11-1-01.png', 1),
  ('os177', 'aula-11-1', 'Triagem Assistida', 'Use IA para resumir curriculos, comparar criterios objetivos e organizar candidatos. Antes disso, anonimizar dados reduz risco e deixa a analise mais justa.', '/slides/m11/aula-11-1-02.png', 2),
  ('os178', 'aula-11-1', 'JD com IA', 'Uma boa descricao de vaga nasce de contexto claro: missao do cargo, responsabilidades, requisitos, diferenciais e etapas do processo seletivo.', '/slides/m11/aula-11-1-03.png', 3),
  ('os179', 'aula-11-1', 'Feedback com IA', 'A IA ajuda a estruturar feedbacks em fato, impacto, orientacao e proximo passo. A conversa final precisa manter empatia, contexto e responsabilidade.', '/slides/m11/aula-11-1-04.png', 4),
  ('os180', 'aula-11-1', 'Onboarding Inteligente', 'Transforme os primeiros 30 dias em plano claro com documentos, acessos, treinamentos, responsaveis e primeiras entregas adaptadas ao cargo.', '/slides/m11/aula-11-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q36', 'aula-11-1', 'Quiz: IA no RH')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p106', 'q36', 'Risco principal no RH com IA?', '[{"id":"a","texto":"Bateria."},{"id":"b","texto":"Dados pessoais e viés."},{"id":"c","texto":"Cor."},{"id":"d","texto":"Som."}]'::jsonb, 'b', 1),
  ('p107', 'q36', 'Decisão final deve ser...', '[{"id":"a","texto":"Da IA."},{"id":"b","texto":"Humana."},{"id":"c","texto":"Sorteio."},{"id":"d","texto":"Aleatória."}]'::jsonb, 'b', 2),
  ('p108', 'q36', 'O que anonimizar?', '[{"id":"a","texto":"Nome e dados de candidato."},{"id":"b","texto":"Cor."},{"id":"c","texto":"Fonte."},{"id":"d","texto":"Logo."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-11-2', 'm11', 'IA no Financeiro', 'Conciliação, análise de despesa e relatórios.', 'Conciliação, análise de despesa e relatórios.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar IA em rotinas financeiras.</p><h3>📖 Explicação</h3><div><p>No financeiro: extração de dados de notas fiscais, conciliação bancária assistida, análise de despesa por categoria, relatórios gerenciais. IA reduz horas de tarefa repetitiva.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Extração de dados de NFs.</li><li>Análise de despesa por centro de custo.</li><li>Relatório gerencial.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Use Power Automate + AI Builder para extrair NFs.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar em totais sem validar.</li></ul><h3>📌 Resumo final</h3><p>IA acelera. Você fecha os números.</p><h3>✏️ Exercício de fixação</h3><p>Use IA para resumir suas despesas do mês por categoria.</p>', '', 2, 25, true, 'Aplicar IA em rotinas financeiras.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'O financeiro é o playground perfeito da IA — mas valida tudo.', 'IA acelera. Você fecha os números.', 'Apresentar IA no Financeiro: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Use IA para resumir suas despesas do mês por categoria.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os181', 'aula-11-2', 'IA no Financeiro', 'No financeiro, a IA acelera extracao de dados, conciliacao, analise de despesas e relatorios. Rapidez ajuda, mas rigor nos numeros continua obrigatorio.', '/slides/m11/aula-11-2-01.png', 1),
  ('os182', 'aula-11-2', 'Extrair Dados', 'Notas fiscais e documentos podem virar tabelas com fornecedor, data, valor, categoria e centro de custo. Campos criticos precisam ser conferidos na origem.', '/slides/m11/aula-11-2-02.png', 2),
  ('os183', 'aula-11-2', 'Analise de Despesas', 'A IA ajuda a encontrar padroes, categorias, anomalias e variacoes. Depois, o Excel ou sistema financeiro confirma valores, filtros e premissas.', '/slides/m11/aula-11-2-03.png', 3),
  ('os184', 'aula-11-2', 'Relatorio Gerencial', 'Relatorio bom conecta numero, causa, impacto e recomendacao. Use IA para transformar dados em explicacao executiva clara e acionavel.', '/slides/m11/aula-11-2-04.png', 4),
  ('os185', 'aula-11-2', 'Checklist Financeiro', 'Antes de confiar, confira totais, periodo, fonte, categoria, duplicidades e aprovacao. A IA acelera a analise, mas voce fecha os numeros.', '/slides/m11/aula-11-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q37', 'aula-11-2', 'Quiz: IA no Financeiro')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p109', 'q37', 'O que IA acelera no financeiro?', '[{"id":"a","texto":"Tarefas repetitivas."},{"id":"b","texto":"Decisão estratégica final."},{"id":"c","texto":"Senha."},{"id":"d","texto":"Login."}]'::jsonb, 'a', 1),
  ('p110', 'q37', 'O que sempre validar?', '[{"id":"a","texto":"Totais."},{"id":"b","texto":"Cor."},{"id":"c","texto":"Fonte."},{"id":"d","texto":"Foto."}]'::jsonb, 'a', 2),
  ('p111', 'q37', 'Ferramenta Microsoft para extrair NFs?', '[{"id":"a","texto":"Power Automate + AI Builder."},{"id":"b","texto":"Photoshop."},{"id":"c","texto":"Outlook."},{"id":"d","texto":"Teams."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-11-3', 'm11', 'IA em Compras', 'Cotações, contratos e análise de fornecedor.', 'Cotações, contratos e análise de fornecedor.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar IA em rotinas de compras.</p><h3>📖 Explicação</h3><div><p>Compras: comparação de cotações, redação de e-mails de negociação, análise de cláusulas contratuais, scoring de fornecedor. Reduz horas e dá visão estratégica.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Comparativo de 3 cotações.</li><li>E-mail de negociação.</li><li>Análise rápida de cláusula contratual.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Sempre revise cláusula contratual com humano antes de assinar.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Confiar em "resumo de contrato" sem ler o original em pontos críticos.</li></ul><h3>📌 Resumo final</h3><p>IA acelera análise. Decisão é sua.</p><h3>✏️ Exercício de fixação</h3><p>Use IA para comparar 2 cotações reais.</p>', '', 3, 25, true, 'Aplicar IA em rotinas de compras.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Compras com IA viram estratégicas. Vem ver como.', 'IA acelera análise. Decisão é sua.', 'Apresentar IA em Compras: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Use IA para comparar 2 cotações reais.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os186', 'aula-11-3', 'IA em Compras', 'Compras com IA fica mais estrategico: comparar propostas, preparar negociacoes, revisar contratos e avaliar fornecedores com criterios mais claros.', '/slides/m11/aula-11-3-01.png', 1),
  ('os187', 'aula-11-3', 'Comparativo de Cotacoes', 'Preco nao e tudo. Compare preco, prazo, condicao, garantia e risco para evitar decisoes baseadas em um unico numero.', '/slides/m11/aula-11-3-02.png', 2),
  ('os188', 'aula-11-3', 'Negociacao com IA', 'A IA ajuda a escrever mensagens firmes, claras e profissionais quando recebe objetivo, limite, argumento, concessao possivel e proxima acao.', '/slides/m11/aula-11-3-03.png', 3),
  ('os189', 'aula-11-3', 'Contratos com IA', 'Use IA para resumir e marcar riscos em clausulas como multa, prazo, reajuste e rescisao. Em pontos criticos, leia o original antes de assinar.', '/slides/m11/aula-11-3-04.png', 4),
  ('os190', 'aula-11-3', 'Scoring de Fornecedor', 'Avalie fornecedores por preco, prazo, qualidade, historico e risco. A pontuacao organiza a escolha, mas a aprovacao final continua humana.', '/slides/m11/aula-11-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q38', 'aula-11-3', 'Quiz: IA em Compras')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p112', 'q38', 'Para cláusula contratual crítica, o que fazer?', '[{"id":"a","texto":"Confiar no resumo."},{"id":"b","texto":"Ler o original."},{"id":"c","texto":"Ignorar."},{"id":"d","texto":"Apagar."}]'::jsonb, 'b', 1),
  ('p113', 'q38', 'IA ajuda em quais tarefas?', '[{"id":"a","texto":"Cotações, negociação, análise."},{"id":"b","texto":"Café."},{"id":"c","texto":"Calculadora."},{"id":"d","texto":"Senha."}]'::jsonb, 'a', 2),
  ('p114', 'q38', 'Decisão final?', '[{"id":"a","texto":"Humana."},{"id":"b","texto":"IA."},{"id":"c","texto":"Sorteio."},{"id":"d","texto":"Random."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-11-4', 'm11', 'IA em Operações', 'POPs, escalas e indicadores.', 'POPs, escalas e indicadores.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar IA em operações e processos.</p><h3>📖 Explicação</h3><div><p>Operações: padronização de processos (POPs), montagem de escalas, monitoramento de indicadores, identificação de gargalos. IA dá clareza sobre onde ajustar.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>POPs padronizados.</li><li>Escala otimizada.</li><li>Alertas de SLA.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comece pelo processo de maior dor.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Otimizar processos pouco relevantes.</li></ul><h3>📌 Resumo final</h3><p>IA mostra o gargalo. Você decide onde investir.</p><h3>✏️ Exercício de fixação</h3><p>Liste 3 processos da operação e priorize 1 para otimizar.</p>', '', 4, 25, true, 'Aplicar IA em operações e processos.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Operações é onde IA faz diferença em escala. Bora descobrir.', 'IA mostra o gargalo. Você decide onde investir.', 'Apresentar IA em Operações: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Liste 3 processos da operação e priorize 1 para otimizar.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os191', 'aula-11-4', 'IA em Operacoes', 'Em operacoes, a IA ajuda a mapear processos, medir indicadores, priorizar ajustes e acompanhar gargalos. Comece pela maior dor operacional.', '/slides/m11/aula-11-4-01.png', 1),
  ('os192', 'aula-11-4', 'Maior Dor Primeiro', 'Nao otimize o que quase nao importa. Priorize processos de alta frequencia e alto impacto, onde o ganho aparece para a equipe e para o cliente.', '/slides/m11/aula-11-4-02.png', 2),
  ('os193', 'aula-11-4', 'Escalas com IA', 'A IA sugere cenarios de escala considerando demanda, disponibilidade, habilidades, folgas e prioridades. O gestor valida restricoes e realidade do time.', '/slides/m11/aula-11-4-03.png', 3),
  ('os194', 'aula-11-4', 'Indicadores e SLA', 'A IA ajuda a explicar variacoes em SLA, tempo medio, volume, atrasos e retrabalho. Indicadores bem definidos viram acoes corretivas melhores.', '/slides/m11/aula-11-4-04.png', 4),
  ('os195', 'aula-11-4', 'Gargalos Operacionais', 'Melhorar operacoes e encontrar o ponto que segura o fluxo, agir sobre a causa, definir responsavel e acompanhar se o atraso caiu.', '/slides/m11/aula-11-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q39', 'aula-11-4', 'Quiz: IA em Operações')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p115', 'q39', 'Por onde começar?', '[{"id":"a","texto":"Maior dor."},{"id":"b","texto":"Menor dor."},{"id":"c","texto":"Sorteio."},{"id":"d","texto":"Aleatório."}]'::jsonb, 'a', 1),
  ('p116', 'q39', 'O que IA entrega em operações?', '[{"id":"a","texto":"Clareza para decidir."},{"id":"b","texto":"Senha."},{"id":"c","texto":"Foto."},{"id":"d","texto":"Música."}]'::jsonb, 'a', 2),
  ('p117', 'q39', 'O que NÃO fazer?', '[{"id":"a","texto":"Otimizar irrelevante."},{"id":"b","texto":"Documentar."},{"id":"c","texto":"Medir."},{"id":"d","texto":"Iterar."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-11-5', 'm11', 'IA no Atendimento', 'Respostas, classificação e resumo de tickets.', 'Respostas, classificação e resumo de tickets.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar IA no atendimento ao cliente.</p><h3>📖 Explicação</h3><div><p>Atendimento: classificação de tickets, sugestão de resposta, resumo de histórico, detecção de sentimento. Atendente fica mais rápido e mais preparado para o contato.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Classificação de tickets.</li><li>Sugestão de resposta.</li><li>Resumo do histórico do cliente.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Cliente sempre fala com humano se quiser.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Forçar bot quando o cliente quer humano.</li></ul><h3>📌 Resumo final</h3><p>IA ajuda o atendente. O atendente atende o cliente.</p><h3>✏️ Exercício de fixação</h3><p>Use IA para classificar 5 tickets seus.</p>', '', 5, 25, true, 'Aplicar IA no atendimento ao cliente.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Atendimento com IA não substitui empatia — multiplica capacidade.', 'IA ajuda o atendente. O atendente atende o cliente.', 'Apresentar IA no Atendimento: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Use IA para classificar 5 tickets seus.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os196', 'aula-11-5', 'IA no Atendimento', 'A IA ajuda a classificar tickets, resumir historico, sugerir respostas e detectar sentimento. O atendente ganha velocidade sem perder empatia.', '/slides/m11/aula-11-5-01.png', 1),
  ('os197', 'aula-11-5', 'Classificar Tickets', 'Tickets podem ser separados por tema, urgencia e rota de atendimento. Prioridade certa organiza a fila e leva cada caso para a equipe correta.', '/slides/m11/aula-11-5-02.png', 2),
  ('os198', 'aula-11-5', 'Resumo do Historico', 'Antes de responder, a IA resume problema, tentativas, promessas, prazo e proximo passo. O atendente entende o contexto sem reler tudo.', '/slides/m11/aula-11-5-03.png', 3),
  ('os199', 'aula-11-5', 'Sugestao de Resposta', 'A IA prepara o rascunho em tom empatico, objetivo, tecnico ou urgente. O atendente adapta, confere dados e aprova a resposta final.', '/slides/m11/aula-11-5-04.png', 4),
  ('os200', 'aula-11-5', 'Sentimento e Escalada', 'Quando o cliente demonstra frustracao, urgencia ou risco, a IA sinaliza prioridade. O atendimento humano assume a rota segura.', '/slides/m11/aula-11-5-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q40', 'aula-11-5', 'Quiz: IA no Atendimento')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p118', 'q40', 'IA substitui o atendente?', '[{"id":"a","texto":"Sim."},{"id":"b","texto":"Não — multiplica."},{"id":"c","texto":"Talvez."},{"id":"d","texto":"Sempre."}]'::jsonb, 'b', 1),
  ('p119', 'q40', 'O cliente deve ter acesso a...', '[{"id":"a","texto":"Humano."},{"id":"b","texto":"Bot apenas."},{"id":"c","texto":"Email apenas."},{"id":"d","texto":"Robô."}]'::jsonb, 'a', 2),
  ('p120', 'q40', 'O que NÃO fazer?', '[{"id":"a","texto":"Forçar bot quando cliente quer humano."},{"id":"b","texto":"Treinar atendente."},{"id":"c","texto":"Medir resultado."},{"id":"d","texto":"Iterar."}]'::jsonb, 'a', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m12', 'M12 - Projeto Final', 'Aplicação prática, plano de adoção e certificação.', 12, 5, true, '/covers/m12-projeto-final-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-12-1', 'm12', 'Aplicação Prática', 'Projeto integrador: aplique tudo no seu trabalho.', 'Projeto integrador: aplique tudo no seu trabalho.', '<h3>🎯 Objetivo da aula</h3><p>Aplicar técnicas do curso em um caso real seu.</p><h3>📖 Explicação</h3><div><p>Hora de juntar. Escolha um processo do seu trabalho. Documente como é hoje. Use prompts, automação e IA Generativa para redesenhá-lo. Meça o ganho. Esse é o seu projeto final.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Redesenho do processo de e-mail de cobrança.</li><li>Pipeline de triagem com IA.</li><li>Dashboard com IA.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Escolha algo que você executa toda semana — mede ganho rápido.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Querer mudar 10 processos. Faça 1, mas faça bem.</li></ul><h3>📌 Resumo final</h3><p>Foque em 1 processo. Aplique, meça, documente.</p><h3>✏️ Exercício de fixação</h3><p>Defina seu projeto: processo escolhido, ganho esperado, prazo.</p>', '', 1, 30, true, 'Aplicar técnicas do curso em um caso real seu.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Hora de aplicar. Escolha 1 processo. Transforme-o. Meça.', 'Foque em 1 processo. Aplique, meça, documente.', 'Apresentar Aplicação Prática: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Defina seu projeto: processo escolhido, ganho esperado, prazo.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os201', 'aula-12-1', 'Projeto Final', 'Escolha um processo real do seu trabalho e mostre a transformacao. O foco e simples: um processo, antes e depois, resultado medido.', '/slides/m12/aula-12-1-01.png', 1),
  ('os202', 'aula-12-1', 'Antes x Depois', 'Compare o processo manual com o processo apoiado por IA. Mostre onde havia demora, retrabalho ou confusao e como a nova versao melhora a rotina.', '/slides/m12/aula-12-1-02.png', 2),
  ('os203', 'aula-12-1', 'O Que Medir', 'Projeto bom termina em evidencia. Meça tempo economizado, qualidade da entrega e custo ou retrabalho reduzido para provar o valor da mudanca.', '/slides/m12/aula-12-1-03.png', 3),
  ('os204', 'aula-12-1', 'Use Tudo Que Aprendeu', 'Combine prompts, documentos, planilhas e automacao em uma solucao simples. O objetivo nao e usar tudo por enfeite, e resolver melhor uma tarefa real.', '/slides/m12/aula-12-1-04.png', 4),
  ('os205', 'aula-12-1', 'Entrega Final', 'Apresente o processo redesenhado, o ganho medido e os proximos passos. A entrega final deve mostrar o que mudou, quanto melhorou e como manter.', '/slides/m12/aula-12-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q41', 'aula-12-1', 'Quiz: Aplicação Prática')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p121', 'q41', 'Quantos processos no projeto final?', '[{"id":"a","texto":"1."},{"id":"b","texto":"10."},{"id":"c","texto":"100."},{"id":"d","texto":"0."}]'::jsonb, 'a', 1),
  ('p122', 'q41', 'O que medir?', '[{"id":"a","texto":"Tempo, qualidade, custo."},{"id":"b","texto":"Cor."},{"id":"c","texto":"Logo."},{"id":"d","texto":"Música."}]'::jsonb, 'a', 2),
  ('p123', 'q41', 'Escolha um processo...', '[{"id":"a","texto":"Que você faz toda semana."},{"id":"b","texto":"Que você nunca faz."},{"id":"c","texto":"Aleatório."},{"id":"d","texto":"Do colega."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-12-2', 'm12', 'Plano de Adoção', 'Como levar IA para a sua equipe.', 'Como levar IA para a sua equipe.', '<h3>🎯 Objetivo da aula</h3><p>Estruturar plano de adoção de IA na sua equipe.</p><h3>📖 Explicação</h3><div><p>Adoção tem 3 pilares: pessoas (treinar), processos (escolher onde aplicar primeiro), políticas (segurança, LGPD, governança). Comece pequeno, mostre ganho, expanda.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Piloto de 30 dias com 3 pessoas.</li><li>Política de uso interno.</li><li>Treinamento por área.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Mostre ROI antes de pedir orçamento.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Comprar licença antes de saber se vai usar.</li></ul><h3>📌 Resumo final</h3><p>Pessoas + Processos + Políticas. Piloto. Mede. Escala.</p><h3>✏️ Exercício de fixação</h3><p>Esboce um plano de adoção em 1 página.</p>', '', 2, 25, true, 'Estruturar plano de adoção de IA na sua equipe.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Adoção é jornada. Não evento. Vamos planejar o seu caminho.', 'Pessoas + Processos + Políticas. Piloto. Mede. Escala.', 'Apresentar Plano de Adoção: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Esboce um plano de adoção em 1 página.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os206', 'aula-12-2', 'Plano de Adocao', 'Adotar IA na equipe exige tres pilares: pessoas treinadas, processos bem escolhidos e politicas claras de seguranca, LGPD e revisao humana.', '/slides/m12/aula-12-2-01.png', 1),
  ('os207', 'aula-12-2', 'Piloto de 30 Dias', 'Comece pequeno: tres pessoas, um processo e resultado medido. O piloto reduz risco, gera aprendizado e mostra se vale escalar.', '/slides/m12/aula-12-2-02.png', 2),
  ('os208', 'aula-12-2', 'Treine a Equipe', 'Treinamento bom usa tarefas reais do dia a dia. Demonstre, pratique, revise e repita ate a IA virar parte natural da rotina.', '/slides/m12/aula-12-2-03.png', 3),
  ('os209', 'aula-12-2', 'Governanca e Seguranca', 'IA na empresa precisa de regras claras: dados sensiveis, permissoes, LGPD, revisao humana e registro de uso. Limites protegem pessoas e decisoes.', '/slides/m12/aula-12-2-04.png', 4),
  ('os210', 'aula-12-2', 'ROI Antes de Escalar', 'Antes de comprar mais licencas ou expandir, prove ganho com dados do piloto. Mostre tempo economizado, custo evitado e qualidade melhorada.', '/slides/m12/aula-12-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q42', 'aula-12-2', 'Quiz: Plano de Adoção')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p124', 'q42', 'Quais os 3 pilares de adoção?', '[{"id":"a","texto":"Pessoas, Processos, Políticas."},{"id":"b","texto":"PC, Mouse, Teclado."},{"id":"c","texto":"Café, Bolo, Sono."},{"id":"d","texto":"Foto, Vídeo, Áudio."}]'::jsonb, 'a', 1),
  ('p125', 'q42', 'Como começar?', '[{"id":"a","texto":"Piloto pequeno."},{"id":"b","texto":"Tudo de uma vez."},{"id":"c","texto":"Comprando licença em massa."},{"id":"d","texto":"Sem treinar."}]'::jsonb, 'a', 2),
  ('p126', 'q42', 'O que mostrar antes de escalar?', '[{"id":"a","texto":"ROI."},{"id":"b","texto":"Logo."},{"id":"c","texto":"Cor."},{"id":"d","texto":"Foto."}]'::jsonb, 'a', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-12-3', 'm12', 'Certificação e Próximos Passos', 'Conclua o curso e planeje sua continuidade.', 'Conclua o curso e planeje sua continuidade.', '<h3>🎯 Objetivo da aula</h3><p>Conquistar o certificado e definir próximos passos.</p><h3>📖 Explicação</h3><div><p>Parabéns! Você está pronto. Emita seu certificado, atualize seu LinkedIn, e continue aprendendo: novos modelos chegam todo mês. Mantenha uma rotina semanal de experimentação.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Atualizar LinkedIn.</li><li>Criar rotina de experimentação semanal.</li><li>Trazer 1 colega para o curso.</li></ul><h3>💡 Dicas importantes</h3><ul><li>IA evolui rápido. Reserve 30 min/semana só para explorar novidades.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Parar de praticar.</li></ul><h3>📌 Resumo final</h3><p>Certificou? Praticou? Continue. A jornada começa agora.</p><h3>✏️ Exercício de fixação</h3><p>Defina sua rotina de continuidade: o que estudar a cada semana.</p>', '', 3, 20, true, 'Conquistar o certificado e definir próximos passos.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Você chegou ao fim. E é só o começo. Parabéns.', 'Certificou? Praticou? Continue. A jornada começa agora.', 'Apresentar Certificação e Próximos Passos: contexto, exemplos práticos no escritório, dicas e chamada para prática.', 'Defina sua rotina de continuidade: o que estudar a cada semana.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os211', 'aula-12-3', 'Parabens!', 'Voce completou a jornada. Agora o certificado representa uma habilidade pratica: usar IA com criterio, seguranca e foco em resultado.', '/slides/m12/aula-12-3-01.png', 1),
  ('os212', 'aula-12-3', 'Certificado e LinkedIn', 'Transforme a conclusao do curso em evidencia profissional. Emita o certificado, atualize seu perfil e adicione o projeto final como exemplo real.', '/slides/m12/aula-12-3-02.png', 2),
  ('os213', 'aula-12-3', '30 Minutos por Semana', 'IA muda rapido. Reserve um bloco semanal para testar, aplicar, salvar prompts e compartilhar aprendizados com a equipe.', '/slides/m12/aula-12-3-03.png', 3),
  ('os214', 'aula-12-3', 'Continue Explorando', 'Novas ferramentas surgem o tempo todo. Use metodo: descubra, teste em tarefa real, avalie valor e adote apenas o que ajuda.', '/slides/m12/aula-12-3-04.png', 4),
  ('os215', 'aula-12-3', 'Plano Pessoal de Evolucao', 'A jornada continua quando aprendizado vira habito. Escolha uma tarefa real, salve um prompt, melhore um processo e compartilhe um resultado.', '/slides/m12/aula-12-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q43', 'aula-12-3', 'Quiz: Certificação e Próximos Passos')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p127', 'q43', 'O que fazer após certificar?', '[{"id":"a","texto":"Continuar praticando."},{"id":"b","texto":"Parar."},{"id":"c","texto":"Apagar tudo."},{"id":"d","texto":"Esquecer."}]'::jsonb, 'a', 1),
  ('p128', 'q43', 'IA evolui...', '[{"id":"a","texto":"Rápido — reserve tempo semanal."},{"id":"b","texto":"Lento."},{"id":"c","texto":"Nunca muda."},{"id":"d","texto":"Só de ano em ano."}]'::jsonb, 'a', 2),
  ('p129', 'q43', 'Boa prática contínua?', '[{"id":"a","texto":"Experimentar 1 ferramenta nova / semana."},{"id":"b","texto":"Nada."},{"id":"c","texto":"Esperar."},{"id":"d","texto":"Ler 1 vez por ano."}]'::jsonb, 'a', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m13', 'M13 - Produtividade com IA', 'Agenda inteligente, controle de tarefas, apresentações e o fluxo do dia integrado com IA.', 13, 4, true, '/covers/m13-produtividade-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-13-1', 'm13', 'Agenda Inteligente com IA', 'Priorize o que importa, elimine o ruído e proteja seu tempo produtivo.', 'Matriz de Eisenhower por IA, time blocking e gestão de convites.', '<h3>🎯 Objetivo da aula</h3><p>Usar IA para priorizar a semana, criar blocos de tempo e responder convites com estratégia.</p><h3>📖 Explicação</h3><div><p>A IA aplica a Matriz de Eisenhower em segundos: você lista as tarefas da semana, e ela classifica em Q1 (fazer agora), Q2 (agendar), Q3 (delegar) e Q4 (eliminar), estima o tempo de cada uma e sugere um cronograma. Com time blocking, a IA monta blocos de trabalho profundo, reuniões e e-mails respeitando suas preferências de horário.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Classificar as 10 tarefas da semana em Q1–Q4 com cronograma de 5 dias úteis.</li><li>Criar plano de time blocking com trabalho profundo nas manhãs e buffer entre reuniões.</li><li>Recusar um convite de reunião propondo data alternativa com tom respeitoso.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Defina seu expediente e preferências no prompt — a IA monta a agenda em volta delas.</li><li>Antes de aceitar uma reunião, peça pauta, duração e se sua presença é obrigatória.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Aceitar todos os convites sem filtrar pela matriz de prioridade.</li></ul><h3>📌 Resumo final</h3><p>IA classifica prioridades (Eisenhower), monta time blocking e redige respostas a convites — você protege o tempo produtivo.</p><h3>✏️ Exercício de fixação</h3><p>Liste as 10 tarefas desta semana e peça à IA: classificação Q1–Q4, estimativa de tempo e cronograma para 5 dias.</p>', '', 1, 30, true, 'Usar IA para priorizar a semana, criar blocos de tempo e responder convites com estratégia.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Sua agenda não precisa mandar em você. Nesta aula, a IA vira sua assistente de priorização.', 'Eisenhower com IA, time blocking e respostas estratégicas a convites de reunião.', 'Demonstrar a classificação Q1–Q4 por IA e a criação de um plano de time blocking semanal.', 'Monte seu time blocking da próxima semana com IA usando suas tarefas reais.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os216', 'aula-13-1', 'Agenda Inteligente', 'A IA ajuda a organizar a semana para priorizar o que importa, reduzir ruido e proteger blocos de trabalho produtivo.', '/slides/m13/aula-13-1-01.png', 1),
  ('os217', 'aula-13-1', 'Eisenhower com IA', 'Classifique tarefas em fazer agora, agendar, delegar ou eliminar. A matriz reduz improviso e mostra onde seu tempo deve ir primeiro.', '/slides/m13/aula-13-1-02.png', 2),
  ('os218', 'aula-13-1', 'Time Blocking', 'Transforme uma lista solta de tarefas em agenda executavel. Separe trabalho profundo, reunioes, e-mails, pausas e buffers.', '/slides/m13/aula-13-1-03.png', 3),
  ('os219', 'aula-13-1', 'Convites de Reuniao', 'Antes de aceitar, peça pauta, duracao e confirme se sua presenca e obrigatoria. A IA ajuda a aceitar, recusar ou pedir contexto com elegancia.', '/slides/m13/aula-13-1-04.png', 4),
  ('os220', 'aula-13-1', 'Cronograma Semanal', 'A IA sugere um plano de 5 dias com prioridade, estimativa de tempo e alertas de prazo. Voce ajusta conforme energia e contexto real.', '/slides/m13/aula-13-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q44', 'aula-13-1', 'Quiz: Agenda Inteligente com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p130', 'q44', 'No método Eisenhower com IA, tarefas Q4 devem ser...', '[{"id":"a","texto":"Feitas agora."},{"id":"b","texto":"Agendadas."},{"id":"c","texto":"Delegadas."},{"id":"d","texto":"Eliminadas."}]'::jsonb, 'd', 1),
  ('p131', 'q44', 'O que é time blocking?', '[{"id":"a","texto":"Bloquear o celular."},{"id":"b","texto":"Reservar blocos de tempo na agenda para tipos de trabalho."},{"id":"c","texto":"Recusar todas as reuniões."},{"id":"d","texto":"Trabalhar sem pausas."}]'::jsonb, 'b', 2),
  ('p132', 'q44', 'Antes de aceitar uma reunião, é estratégico pedir...', '[{"id":"a","texto":"Café."},{"id":"b","texto":"Pauta, duração e se sua presença é obrigatória."},{"id":"c","texto":"Mudança de sala."},{"id":"d","texto":"Lista de presentes."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-13-2', 'm13', 'Controle de Tarefas com IA', 'Transforme reuniões, e-mails e anotações em tarefas acionáveis.', 'Captura, estruturação, relatório diário e delegação com IA.', '<h3>🎯 Objetivo da aula</h3><p>Capturar tarefas de qualquer fonte, estruturá-las e gerar relatórios de status com IA.</p><h3>📖 Explicação</h3><div><p>E-mails, atas e anotações soltas viram tarefas estruturadas: a IA extrai cada ação com responsável e prazo. Uma tarefa ideal tem título com verbo de ação, contexto, responsável, deadline, dependências e critério de conclusão. No fim do dia, a IA gera seu relatório standup: o que fiz, o que farei, bloqueios e alertas.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Extrair de um e-mail todas as ações com responsável e prazo sugerido.</li><li>Transformar anotações desorganizadas em lista de tarefas com prioridade e deadline.</li><li>Gerar relatório diário no formato standup para enviar ao time.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Delegue com contexto: tarefa, entrega esperada, deadline, critério de sucesso e a quem recorrer.</li><li>Use a IA para criar lembretes de deadline com o impacto do não cumprimento.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Tarefas sem responsável ou sem critério claro de conclusão.</li></ul><h3>📌 Resumo final</h3><p>IA captura, estrutura e acompanha tarefas — de qualquer fonte para uma lista acionável com relatório diário.</p><h3>✏️ Exercício de fixação</h3><p>Cole as anotações de uma reunião recente e peça à IA todas as ações em formato Quem · O quê · Até quando.</p>', '', 2, 30, true, 'Capturar tarefas de qualquer fonte, estruturá-las e gerar relatórios de status com IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Tarefa esquecida é prazo perdido. Vamos colocar a IA para capturar e cobrar por você.', 'Captura de tarefas de e-mails, atas e anotações; estrutura ideal de tarefa; relatório standup diário.', 'Demonstrar extração de tarefas de uma ata e geração do relatório standup.', 'Gere seu relatório standup de hoje com IA a partir da sua lista real de tarefas.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os221', 'aula-13-2', 'Controle de Tarefas', 'E-mails, atas e anotacoes viram tarefas acionaveis com quem faz, o que entrega, ate quando e com qual prioridade.', '/slides/m13/aula-13-2-01.png', 1),
  ('os222', 'aula-13-2', 'Captura de Tarefas', 'A IA extrai acoes de e-mails, reunioes e notas livres. Tarefa nao capturada vira atraso; tarefa capturada vira compromisso visivel.', '/slides/m13/aula-13-2-02.png', 2),
  ('os223', 'aula-13-2', 'Tarefa Ideal', 'Uma tarefa clara tem verbo, contexto, responsavel, deadline, dependencias e criterio de conclusao. Isso reduz retrabalho e duvida.', '/slides/m13/aula-13-2-03.png', 3),
  ('os224', 'aula-13-2', 'Relatorio Standup', 'Resuma o dia em quatro blocos: fiz hoje, farei amanha, bloqueios e alertas. O time acompanha progresso sem longas reunioes.', '/slides/m13/aula-13-2-04.png', 4),
  ('os225', 'aula-13-2', 'Delegacao com Contexto', 'Delegar bem e explicar contexto, entrega esperada, prazo, criterio de sucesso e onde buscar apoio. Clareza acompanha a tarefa.', '/slides/m13/aula-13-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q45', 'aula-13-2', 'Quiz: Controle de Tarefas com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p133', 'q45', 'Uma tarefa bem estruturada começa com...', '[{"id":"a","texto":"Um emoji."},{"id":"b","texto":"Verbo de ação + objeto claro."},{"id":"c","texto":"O nome do chefe."},{"id":"d","texto":"A data de criação."}]'::jsonb, 'b', 1),
  ('p134', 'q45', 'O relatório standup contém...', '[{"id":"a","texto":"Apenas elogios."},{"id":"b","texto":"Feito, próximo, bloqueios e alertas."},{"id":"c","texto":"Histórico de 1 ano."},{"id":"d","texto":"Somente prazos."}]'::jsonb, 'b', 2),
  ('p135', 'q45', 'Ao delegar com IA, inclua sempre...', '[{"id":"a","texto":"Pressão e urgência."},{"id":"b","texto":"Contexto, entrega, deadline e critério de sucesso."},{"id":"c","texto":"Só o título da tarefa."},{"id":"d","texto":"Cópia para toda a empresa."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-13-3', 'm13', 'Apresentações e Roteiros com IA', 'Da ideia à apresentação executiva pronta — com estrutura de narrativa profissional.', 'Narrativa, roteiro slide a slide, conteúdo e notas do apresentador.', '<h3>🎯 Objetivo da aula</h3><p>Construir apresentações completas com IA: narrativa, estrutura, conteúdo por slide e notas de fala.</p><h3>📖 Explicação</h3><div><p>Antes dos slides, a narrativa: com BAB + PARA você define o problema, a ação desejada do público e o argumento que conecta os dois. A IA gera a estrutura slide a slide com mensagem principal de cada um, e depois desenvolve cada slide: título forte, bullets enxutos, visual sugerido e script de fala de 60 segundos.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Gerar estrutura de 8 slides: capa, problema, impacto, solução, como funciona, resultados, investimento, CTA.</li><li>Desenvolver um slide específico com título, mensagem, bullets, visual e nota do apresentador.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Peça consistência: "Mantenha coerência com o slide anterior [colar texto]".</li><li>Notas do apresentador: gancho, dados de suporte, transição, objeções prováveis e call-to-action.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Começar pelos slides sem definir a narrativa e a ação desejada do público.</li></ul><h3>📌 Resumo final</h3><p>Narrativa primeiro (BAB + PARA), depois estrutura, conteúdo por slide e notas de fala — tudo acelerado pela IA.</p><h3>✏️ Exercício de fixação</h3><p>Escolha uma ideia que você precisa apresentar e peça à IA a estrutura completa com mensagem principal de cada slide.</p>', '', 3, 35, true, 'Construir apresentações completas com IA: narrativa, estrutura, conteúdo por slide e notas de fala.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Apresentação boa começa antes do primeiro slide. A IA vira seu co-autor de narrativa.', 'Estrutura de narrativa com BAB e PARA, roteiro slide a slide e notas do apresentador com IA.', 'Do brief à estrutura de 8 slides gerada por IA, com desenvolvimento de um slide completo.', 'Gere a estrutura de uma apresentação real sua com título e mensagem principal por slide.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os226', 'aula-13-3', 'Apresentacoes com IA', 'Apresentacao boa comeca pela narrativa, nao pelo layout. A IA ajuda a sair do brief para roteiro, slides e fala.', '/slides/m13/aula-13-3-01.png', 1),
  ('os227', 'aula-13-3', 'BAB + PARA', 'Defina o antes, o depois e a ponte. Depois conecte publico, acao desejada e argumento central para orientar toda a apresentacao.', '/slides/m13/aula-13-3-02.png', 2),
  ('os228', 'aula-13-3', 'Roteiro Slide a Slide', 'Cada slide precisa defender uma mensagem. A IA cria a estrutura, mas voce valida se a sequencia leva o publico para a decisao certa.', '/slides/m13/aula-13-3-03.png', 3),
  ('os229', 'aula-13-3', 'Conteudo por Slide', 'Peça titulo forte, mensagem principal, 3 a 5 bullets, visual sugerido e nota do apresentador. O slide fica objetivo e apresentavel.', '/slides/m13/aula-13-3-04.png', 4),
  ('os230', 'aula-13-3', 'Notas do Apresentador', 'Notas bem feitas trazem gancho, dado de suporte, transicao, objecao provavel e CTA. Elas ajudam a falar com seguranca em 60 segundos.', '/slides/m13/aula-13-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q46', 'aula-13-3', 'Quiz: Apresentações e Roteiros com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p136', 'q46', 'O que vem antes de montar os slides?', '[{"id":"a","texto":"Escolher a fonte."},{"id":"b","texto":"Definir a narrativa e a ação desejada do público."},{"id":"c","texto":"Escolher as cores."},{"id":"d","texto":"Imprimir o roteiro."}]'::jsonb, 'b', 1),
  ('p137', 'q46', 'A nota do apresentador gerada pela IA deve conter...', '[{"id":"a","texto":"O texto integral dos slides."},{"id":"b","texto":"Gancho, dados, transição, objeções e CTA."},{"id":"c","texto":"Apenas a duração."},{"id":"d","texto":"Piadas obrigatórias."}]'::jsonb, 'b', 2),
  ('p138', 'q46', 'Para coerência entre slides, peça à IA...', '[{"id":"a","texto":"Slides idênticos."},{"id":"b","texto":"Manter consistência com o slide anterior."},{"id":"c","texto":"Ignorar o contexto."},{"id":"d","texto":"Usar outro idioma."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-13-4', 'm13', 'Um Dia de Trabalho com IA Integrada', 'Como e-mail, agenda, tarefas, planilhas, documentos e apresentações se conectam em um fluxo real.', 'O fluxo completo do dia com IA e o desafio prático integrador.', '<h3>🎯 Objetivo da aula</h3><p>Integrar as 6 frentes de IA em um fluxo único de trabalho e medir o ganho de tempo.</p><h3>📖 Explicação</h3><div><p>Quando e-mail, agenda, tarefas, planilhas, documentos e apresentações usam IA de forma integrada, o ganho acumulado chega a cerca de 6h15 por dia — 31h por semana, 125h por mês por colaborador. A IA não substitui: você pensa, decide e cria; ela executa mais rápido o que você já sabe fazer.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Triagem matinal de e-mails → tarefas extraídas → agenda priorizada → relatório no fim do dia.</li><li>Dados da planilha → sumário executivo → slide de apresentação para a liderança.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Comece integrando duas frentes (e-mail + tarefas) e expanda aos poucos.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Tentar adotar as 6 frentes no mesmo dia e abandonar tudo na primeira semana.</li></ul><h3>📌 Resumo final</h3><p>A integração das 6 frentes economiza ~6h15/dia. Você decide, a IA executa.</p><h3>✏️ Exercício de fixação</h3><p>Complete o desafio integrador: e-mail (10 min), agenda (8), tarefas (8), planilha (8), documento (8) e apresentação (10).</p>', '', 4, 25, true, 'Integrar as 6 frentes de IA em um fluxo único de trabalho e medir o ganho de tempo.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Hora de juntar tudo: um dia inteiro de trabalho com IA do início ao fim.', 'Fluxo integrado de IA nas 6 frentes do dia: até 6h15 economizadas por dia.', 'Simular um dia de trabalho usando IA em cada frente, somando o tempo economizado.', 'Execute o desafio das 6 frentes com situações reais da sua rotina e anote o tempo economizado.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os231', 'aula-13-4', 'IA Integrada', 'O maior ganho aparece quando e-mail, agenda, tarefas, planilhas, documentos e apresentacoes se conectam em um fluxo real de trabalho.', '/slides/m13/aula-13-4-01.png', 1),
  ('os232', 'aula-13-4', '6 Frentes Conectadas', 'IA integrada nao e ferramenta isolada. E um sistema de apoio para o dia inteiro, sempre com revisao humana no centro.', '/slides/m13/aula-13-4-02.png', 2),
  ('os233', 'aula-13-4', '6h15 por Dia', 'Pequenos ganhos em varias tarefas se acumulam. A estimativa de produtividade recuperada depende da rotina, mas o efeito composto e real.', '/slides/m13/aula-13-4-03.png', 3),
  ('os234', 'aula-13-4', 'Desafio Integrador', 'Execute seis tarefas reais com IA: e-mail, agenda, tarefas, planilha, documento e apresentacao. No fim, registre o tempo economizado.', '/slides/m13/aula-13-4-04.png', 4),
  ('os235', 'aula-13-4', 'A IA Nao Substitui', 'Voce pensa, decide e cria. A IA organiza, rascunha e acelera. A responsabilidade e a decisao final continuam humanas.', '/slides/m13/aula-13-4-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q47', 'aula-13-4', 'Quiz: Um Dia de Trabalho com IA Integrada')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p139', 'q47', 'Qual o papel da IA no fluxo integrado?', '[{"id":"a","texto":"Substituir o profissional."},{"id":"b","texto":"Executar mais rápido o que você já sabe fazer."},{"id":"c","texto":"Tomar decisões finais."},{"id":"d","texto":"Eliminar reuniões."}]'::jsonb, 'b', 1),
  ('p140', 'q47', 'Como adotar as 6 frentes com sucesso?', '[{"id":"a","texto":"Todas no mesmo dia."},{"id":"b","texto":"Começar por duas e expandir aos poucos."},{"id":"c","texto":"Nunca integrar."},{"id":"d","texto":"Só usar e-mail."}]'::jsonb, 'b', 2),
  ('p141', 'q47', 'O ganho estimado da integração completa é de cerca de...', '[{"id":"a","texto":"10 minutos por dia."},{"id":"b","texto":"6h15 por dia."},{"id":"c","texto":"1h por mês."},{"id":"d","texto":"Nenhum ganho."}]'::jsonb, 'b', 3)
INSERT INTO public.modulos (id, titulo, descricao, ordem, carga_horaria, ativo, cover_image, created_at) VALUES
  ('m14', 'M14 - Instagram & LinkedIn com IA', 'Conteúdo, legendas, hashtags, automações, networking e calendário editorial com IA.', 14, 4, true, '/covers/m14-instagram-linkedin-v2.webp', '2024-01-01')
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-14-1', 'm14', 'Instagram com IA', 'Calendário editorial, legendas, Reels, hashtags, agendamento e métricas com IA.', '7 aplicações práticas — do planejamento à análise de métricas.', '<h3>🎯 Objetivo da aula</h3><p>Planejar, criar e analisar conteúdo de Instagram com apoio de IA.</p><h3>📖 Explicação</h3><div><p>A IA cobre todo o ciclo do Instagram: calendário editorial mensal, legendas com gancho + desenvolvimento + CTA + hashtags, roteiros de Reels cena a cena, scripts de carrossel, conjuntos estratégicos de hashtags e análise de métricas do Insights. O agendamento fica por conta do Meta Business Suite (grátis).</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Calendário editorial do mês com dia, formato, tema, gancho e CTA de cada post.</li><li>Roteiro de Reels de 30s com texto na tela, narração, ação visual e duração por cena.</li><li>Análise de métricas: o que funciona, o que melhorar e 3 testes A/B.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Monte 3 conjuntos de hashtags: alcance amplo (>1M), nicho médio (100k–1M) e nicho específico (<100k).</li><li>Gancho nos 3 primeiros segundos do Reels e na 1ª linha da legenda.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Publicar sem calendário e medir nada — consistência supera perfeição.</li></ul><h3>📌 Resumo final</h3><p>IA planeja, escreve e analisa; Meta Business Suite agenda de graça; você decide e publica.</p><h3>✏️ Exercício de fixação</h3><p>Gere o calendário editorial do próximo mês para o seu perfil com o prompt da aula.</p>', '', 1, 40, true, 'Planejar, criar e analisar conteúdo de Instagram com apoio de IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Do planejamento ao Reels pronto: o Instagram inteiro acelerado por IA.', 'Calendário editorial, legendas, Reels, hashtags, agendamento e métricas com IA.', 'Gerar calendário, legenda e roteiro de Reels ao vivo com IA.', 'Crie 1 legenda educativa completa (gancho, desenvolvimento, CTA, hashtags) para um post real.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os236', 'aula-14-1', 'Instagram com IA', 'A IA acelera o ciclo inteiro do Instagram: planejar, criar, agendar, publicar, medir e melhorar. A estrategia e a decisao continuam humanas.', '/slides/m14/aula-14-1-01.png', 1),
  ('os237', 'aula-14-1', 'Planejamento Mensal', 'Calendario editorial com IA transforma improviso em consistencia. Defina dia, formato, tema, gancho, CTA, status e responsavel.', '/slides/m14/aula-14-1-02.png', 2),
  ('os238', 'aula-14-1', 'Legendas que Engajam', 'Uma legenda forte prende atencao na primeira linha, entrega valor em paragrafos curtos, chama para acao e usa hashtags relevantes.', '/slides/m14/aula-14-1-03.png', 3),
  ('os239', 'aula-14-1', 'Reels e Carrossel', 'A IA transforma uma ideia em roteiro cena a cena ou slide a slide, com gancho rapido, sequencia visual e chamada para acao.', '/slides/m14/aula-14-1-04.png', 4),
  ('os240', 'aula-14-1', 'Hashtags e Metricas', 'Combine hashtags amplas, de nicho e locais. Depois acompanhe alcance, salvamentos, comentarios e cliques para melhorar o proximo mes.', '/slides/m14/aula-14-1-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q48', 'aula-14-1', 'Quiz: Instagram com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p142', 'q48', 'A 1ª linha de uma legenda deve conter...', '[{"id":"a","texto":"Hashtags."},{"id":"b","texto":"O gancho que para o scroll."},{"id":"c","texto":"A assinatura."},{"id":"d","texto":"O link."}]'::jsonb, 'b', 1),
  ('p143', 'q48', 'Qual ferramenta gratuita agenda posts do Instagram?', '[{"id":"a","texto":"Photoshop."},{"id":"b","texto":"Meta Business Suite."},{"id":"c","texto":"Excel."},{"id":"d","texto":"Zapier."}]'::jsonb, 'b', 2),
  ('p144', 'q48', 'Um bom mix de hashtags combina...', '[{"id":"a","texto":"Só as mais populares."},{"id":"b","texto":"Alcance amplo + nicho médio + nicho específico + localidade."},{"id":"c","texto":"Hashtags aleatórias."},{"id":"d","texto":"Nenhuma hashtag."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-14-2', 'm14', 'LinkedIn com IA', 'Autoridade profissional, networking e geração de oportunidades com IA.', 'Perfil otimizado, 4 formatos de post, mensagens de conexão e agendamento.', '<h3>🎯 Objetivo da aula</h3><p>Otimizar o perfil, criar posts de alto impacto e fazer networking estratégico com IA.</p><h3>📖 Explicação</h3><div><p>No LinkedIn, a IA otimiza headline e resumo, gera posts em 4 formatos (autoridade, storytelling, posicionamento e conquista), escreve mensagens de conexão que são aceitas e sequências de follow-up que geram oportunidades. O agendamento pode ser nativo (ícone de relógio) ou via Buffer gratuito.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>5 opções de headline combinando cargo + resultado + diferencial + palavras-chave.</li><li>Post de autoridade com gancho forte, 3 insights práticos, caso real e pergunta para debate.</li><li>Sequência de 3 mensagens: agradecer, aprofundar e pedir a reunião de forma natural.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Mensagem de conexão: mencione algo específico do perfil, 1 frase de motivo, sem pitch — máx 300 caracteres.</li><li>Resumo "Sobre": impacto na 1ª frase, trajetória, conquistas com números, valores e CTA.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Enviar pitch de venda na primeira mensagem de conexão.</li></ul><h3>📌 Resumo final</h3><p>Perfil otimizado + posts consistentes + networking com contexto = autoridade e oportunidades.</p><h3>✏️ Exercício de fixação</h3><p>Gere 5 headlines para o seu perfil com o prompt da aula e escolha a melhor.</p>', '', 2, 40, true, 'Otimizar o perfil, criar posts de alto impacto e fazer networking estratégico com IA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'LinkedIn é vitrine profissional. Com IA, sua autoridade cresce post a post.', 'Headline e resumo otimizados, 4 formatos de post, mensagens de conexão e agendamento.', 'Otimizar um perfil real e gerar um post de autoridade com IA.', 'Escreva e publique 1 post de autoridade gerado e revisado com IA.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os241', 'aula-14-2', 'LinkedIn com IA', 'No LinkedIn, a IA ajuda a transformar experiencia em autoridade visivel, posts consistentes, networking com contexto e oportunidades profissionais.', '/slides/m14/aula-14-2-01.png', 1),
  ('os242', 'aula-14-2', 'Perfil Otimizado', 'Um perfil forte mostra cargo, resultado, diferencial, palavras-chave e chamada para contato. A IA ajuda a melhorar headline, sobre e experiencias.', '/slides/m14/aula-14-2-02.png', 2),
  ('os243', 'aula-14-2', 'Posts de Alto Impacto', 'Use formatos como autoridade, storytelling, posicionamento e conquista. Post bom cria percepcao de autoridade e abre conversa qualificada.', '/slides/m14/aula-14-2-03.png', 3),
  ('os244', 'aula-14-2', 'Networking com IA', 'Mensagem boa menciona algo especifico do perfil, explica o motivo da conexao e evita pitch na primeira abordagem. Contexto vem antes do pedido.', '/slides/m14/aula-14-2-04.png', 4),
  ('os245', 'aula-14-2', 'Calendario LinkedIn', 'Autoridade cresce com consistencia. Planeje quatro semanas com textos, carrosseis, enquetes e artigos alinhados a autoridade, networking ou negocios.', '/slides/m14/aula-14-2-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q49', 'aula-14-2', 'Quiz: LinkedIn com IA')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p145', 'q49', 'Uma boa mensagem de conexão...', '[{"id":"a","texto":"Já vende no primeiro contato."},{"id":"b","texto":"Menciona algo específico do perfil e não faz pitch."},{"id":"c","texto":"É genérica para todos."},{"id":"d","texto":"Tem 2000 caracteres."}]'::jsonb, 'b', 1),
  ('p146', 'q49', 'O post de storytelling abre com...', '[{"id":"a","texto":"A conclusão."},{"id":"b","texto":"O momento mais tenso da história."},{"id":"c","texto":"Hashtags."},{"id":"d","texto":"Um pedido de like."}]'::jsonb, 'b', 2),
  ('p147', 'q49', 'Na sequência de networking, o pedido de reunião vem...', '[{"id":"a","texto":"Na 1ª mensagem."},{"id":"b","texto":"Na 3ª mensagem, de forma natural."},{"id":"c","texto":"Nunca."},{"id":"d","texto":"Antes da conexão."}]'::jsonb, 'b', 3)
INSERT INTO public.aulas (id, modulo_id, titulo, descricao, descricao_curta, conteudo_html, video_url, ordem, duracao_min, ativo, objetivo, passo_a_passo, dicas, erros_comuns, resumo, exercicio, narracao, resumo_audio, roteiro_video, atividade_pratica, video_titulo, video_canal, video_duracao, created_at) VALUES
  ('aula-14-3', 'm14', 'Instagram vs LinkedIn: Estratégia por Plataforma', 'Objetivo, conteúdo e ferramentas de cada plataforma — lado a lado.', 'Quando usar cada rede e como manter a consistência.', '<h3>🎯 Objetivo da aula</h3><p>Escolher a plataforma, o formato e a frequência certos para cada objetivo.</p><h3>📖 Explicação</h3><div><p>Instagram: marca, venda B2C e engajamento, com conteúdo visual e emocional (Reels, carrossel, Stories), 3–7× por semana. LinkedIn: autoridade, networking, B2B e carreira, com conteúdo educativo, cases e dados (post de texto, carrossel PDF, poll), 3–5× por semana. Em ambos, a IA escreve — você decide, publica e se relaciona.</p></div><h3>💼 Exemplos no escritório</h3><ul><li>Lançamento B2C → Reels no Instagram; case de projeto → post de autoridade no LinkedIn.</li><li>Mesmo tema adaptado: tom leve e visual no Instagram, profissional e com dados no LinkedIn.</li></ul><h3>💡 Dicas importantes</h3><ul><li>Consistência supera perfeição: comece com 1 post, depois 3, depois o mês inteiro.</li></ul><h3>⚠️ Erros comuns</h3><ul><li>Postar o mesmo texto idêntico nas duas plataformas sem adaptar tom e formato.</li></ul><h3>📌 Resumo final</h3><p>Cada plataforma tem objetivo, tom e formato próprios. A IA acelera a produção; a estratégia é sua.</p><h3>✏️ Exercício de fixação</h3><p>Pegue 1 tema do seu trabalho e crie com IA duas versões: uma para Instagram e uma para LinkedIn.</p>', '', 3, 20, true, 'Escolher a plataforma, o formato e a frequência certos para cada objetivo.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'Mesma mensagem, plataformas diferentes. Aprenda a adaptar em vez de duplicar.', 'Instagram para B2C e engajamento; LinkedIn para autoridade e B2B. Adapte tom e formato.', 'Comparar lado a lado o mesmo tema publicado nas duas plataformas.', 'Monte seu plano: qual plataforma priorizar, frequência e os 4 primeiros temas.', NULL, NULL, NULL, '2024-01-01')
INSERT INTO public.slides (id, aula_id, titulo, texto, imagem_url, ordem) VALUES
  ('os246', 'aula-14-3', 'Instagram vs LinkedIn', 'Cada plataforma tem um papel. Instagram favorece marca, visual e engajamento; LinkedIn favorece autoridade, carreira, B2B e networking.', '/slides/m14/aula-14-3-01.png', 1),
  ('os247', 'aula-14-3', 'Mesmo Tema, Duas Versoes', 'Nao copie o mesmo texto nas duas redes. Adapte tom, formato e objetivo para o comportamento de cada publico.', '/slides/m14/aula-14-3-02.png', 2),
  ('os248', 'aula-14-3', 'Ferramentas por Plataforma', 'Cada plataforma tem fluxos proprios para criar, agendar, automatizar e analisar. Use IA para produzir e interpretar dados com criterio.', '/slides/m14/aula-14-3-03.png', 3),
  ('os249', 'aula-14-3', 'Consistencia Supera Perfeicao', 'Comece com um post, depois tres, depois o mes inteiro. O melhor plano e aquele que voce consegue manter, medir e melhorar.', '/slides/m14/aula-14-3-04.png', 4),
  ('os250', 'aula-14-3', 'IA Escreve. Voce Decide.', 'A IA rascunha, voce revisa, publica, responde e aprende. Estrategia, voz e relacionamento continuam sendo responsabilidade humana.', '/slides/m14/aula-14-3-05.png', 5)
INSERT INTO public.quizzes (id, aula_id, titulo) VALUES
  ('q50', 'aula-14-3', 'Quiz: Instagram vs LinkedIn: Estratégia por Plataforma')
INSERT INTO public.perguntas (id, quiz_id, texto, opcoes, resposta_correta, ordem) VALUES
  ('p148', 'q50', 'Para gerar autoridade B2B, a melhor plataforma é...', '[{"id":"a","texto":"Instagram."},{"id":"b","texto":"LinkedIn."},{"id":"c","texto":"Stories."},{"id":"d","texto":"ManyChat."}]'::jsonb, 'b', 1),
  ('p149', 'q50', 'O conteúdo que mais engaja no Instagram é...', '[{"id":"a","texto":"Educativo com dados."},{"id":"b","texto":"Visual e emocional."},{"id":"c","texto":"Relatórios técnicos."},{"id":"d","texto":"Artigos longos."}]'::jsonb, 'b', 2),
  ('p150', 'q50', '"Consistência supera perfeição" significa...', '[{"id":"a","texto":"Publicar qualquer coisa."},{"id":"b","texto":"Manter frequência regular em vez de esperar o post perfeito."},{"id":"c","texto":"Nunca revisar."},{"id":"d","texto":"Postar 1 vez por ano."}]'::jsonb, 'b', 3)
